// /api/admin/pipeline-snapshot — read-only snapshot of the CRM pipeline
// for boardroom strategy sessions. Aggregates 5 views in one call:
//
//   1. Contacts grouped by pipeline_stage
//   2. Active deals (contacts with charter_fee > 0) sorted desc
//   3. Pending payments (charter_fee > 0 AND payment_status = 'pending')
//   4. Stale warm leads (in active stages, no activity 7+ days)
//   5. Source breakdown for the active pipeline
//
// Schema notes (as of 2026-04-25):
//   - There is NO separate `deals` table — deal fields are denormalized
//     into `contacts` (charter_fee, commission_earned, charter_vessel,
//     charter_start_date, payment_status). The "deals" abstraction
//     lives in dashboard logic, not the DB.
//   - pipeline_stage is a FK (pipeline_stage_id → pipeline_stages.id),
//     so we resolve to the human-readable name via inner join.
//   - Activities link by contact_id, not contact_email.
//
// Read-only. No mutations. Safe to call from chat/cron/CLI.

import { NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const maxDuration = 60;

const ACTIVE_STAGE_NAMES = [
  "Warm",
  "Hot",
  "Negotiation",
  "Proposal Sent",
  "Meeting Booked",
  "Contract Sent",
];

const TERMINAL_OR_NEW = ["Lost", "Won", "Closed Won", "Closed Lost", "New", "New Lead"];

export async function GET() {
  const sb = createServiceClient();
  const out: any = { generated_at: new Date().toISOString() };

  // ─── 1. Contacts per pipeline_stage ───────────────────────────────
  const { data: stageRows, error: e1 } = await sb
    .from("contacts")
    .select("pipeline_stage:pipeline_stages(name), id")
    .limit(20000);
  if (e1) out.errors_1 = e1.message;
  const stageCounts: Record<string, number> = {};
  for (const r of stageRows ?? []) {
    const stage =
      Array.isArray((r as any).pipeline_stage)
        ? ((r as any).pipeline_stage[0]?.name ?? "Unknown")
        : ((r as any).pipeline_stage?.name ?? "Unknown");
    stageCounts[stage] = (stageCounts[stage] ?? 0) + 1;
  }
  out.contacts_by_stage = Object.entries(stageCounts)
    .sort((a, b) => b[1] - a[1])
    .map(([stage, count]) => ({ stage, count }));
  out.total_contacts = (stageRows ?? []).length;

  // ─── 2. Active deals (charter_fee > 0) ─────────────────────────────
  const { data: deals, error: e2 } = await sb
    .from("contacts")
    .select(
      "first_name, last_name, email, charter_vessel, charter_start_date, charter_end_date, charter_fee, commission_earned, commission_rate, payment_status, pipeline_stage:pipeline_stages(name)",
    )
    .gt("charter_fee", 0)
    .order("charter_fee", { ascending: false });
  if (e2) out.errors_2 = e2.message;
  out.deals = (deals ?? []).map((d: any) => ({
    name: [d.first_name, d.last_name].filter(Boolean).join(" ") || "—",
    email: d.email,
    vessel: d.charter_vessel,
    start_date: d.charter_start_date,
    end_date: d.charter_end_date,
    charter_fee: d.charter_fee,
    commission_earned: d.commission_earned,
    commission_rate: d.commission_rate,
    payment_status: d.payment_status,
    stage: Array.isArray(d.pipeline_stage)
      ? (d.pipeline_stage[0]?.name ?? null)
      : (d.pipeline_stage?.name ?? null),
  }));
  out.pipeline_value_eur = (deals ?? []).reduce(
    (sum: number, d: any) => sum + (Number(d.charter_fee) || 0),
    0,
  );
  out.commission_upside_eur = (deals ?? []).reduce(
    (sum: number, d: any) => sum + (Number(d.commission_earned) || 0),
    0,
  );

  // ─── 3. Pending payments ───────────────────────────────────────────
  out.pending_payments = (deals ?? [])
    .filter((d: any) => (d.payment_status ?? "").toLowerCase() === "pending")
    .map((d: any) => ({
      name: [d.first_name, d.last_name].filter(Boolean).join(" ") || "—",
      email: d.email,
      vessel: d.charter_vessel,
      start_date: d.charter_start_date,
      charter_fee: d.charter_fee,
    }));
  out.pending_payments_total_eur = out.pending_payments.reduce(
    (sum: number, d: any) => sum + (Number(d.charter_fee) || 0),
    0,
  );

  // ─── 4. Stale warm leads (active stage, no activity 7+ days) ──────
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const { data: stageList } = await sb
    .from("pipeline_stages")
    .select("id, name");
  const activeStageIds = (stageList ?? [])
    .filter((s: any) => ACTIVE_STAGE_NAMES.includes(s.name))
    .map((s: any) => s.id);

  const { data: activeContacts, error: e4 } = await sb
    .from("contacts")
    .select(
      "id, first_name, last_name, email, last_activity_at, pipeline_stage:pipeline_stages(name)",
    )
    .in("pipeline_stage_id", activeStageIds)
    .limit(1000);
  if (e4) out.errors_4 = e4.message;

  const stale = (activeContacts ?? [])
    .map((c: any) => {
      const last = c.last_activity_at ? new Date(c.last_activity_at) : null;
      if (!last) return null;
      const days = Math.floor(
        (Date.now() - last.getTime()) / (1000 * 60 * 60 * 24),
      );
      if (days < 7) return null;
      return {
        name:
          [c.first_name, c.last_name].filter(Boolean).join(" ") || "—",
        email: c.email,
        stage: Array.isArray(c.pipeline_stage)
          ? c.pipeline_stage[0]?.name
          : c.pipeline_stage?.name,
        last_activity: c.last_activity_at,
        days_stale: days,
      };
    })
    .filter(Boolean)
    .sort((a: any, b: any) => b.days_stale - a.days_stale);
  out.stale_warm_leads = stale.slice(0, 20);

  // ─── 5. Source breakdown for active pipeline ──────────────────────
  // We need contacts in non-terminal stages, grouped by source × stage.
  const terminalIds = (stageList ?? [])
    .filter((s: any) => TERMINAL_OR_NEW.includes(s.name))
    .map((s: any) => s.id);
  const { data: sourceContacts, error: e5 } = await sb
    .from("contacts")
    .select("source, pipeline_stage:pipeline_stages(name), pipeline_stage_id")
    .not("pipeline_stage_id", "in", `(${terminalIds.join(",") || "0"})`)
    .limit(10000);
  if (e5) out.errors_5 = e5.message;

  const sourceMap: Record<string, Record<string, number>> = {};
  for (const c of sourceContacts ?? []) {
    const src = (c as any).source || "unknown";
    const stage =
      Array.isArray((c as any).pipeline_stage)
        ? (c as any).pipeline_stage[0]?.name ?? "Unknown"
        : (c as any).pipeline_stage?.name ?? "Unknown";
    sourceMap[src] = sourceMap[src] || {};
    sourceMap[src][stage] = (sourceMap[src][stage] ?? 0) + 1;
  }
  out.source_breakdown = Object.entries(sourceMap)
    .map(([source, stages]) => ({
      source,
      stages,
      total: Object.values(stages).reduce((a, b) => a + b, 0),
    }))
    .sort((a, b) => b.total - a.total);

  return NextResponse.json(out);
}

// Cleanup orphan pending_approval / duplicate scheduled rows.
//
// After the 2026-04-22 approval gate landed, multiple generate-weekly
// runs piled captions into pending_approval that nobody approved. After
// the auto-mode fix (2026-04-28) those rows would silently flood the
// publish queue. This admin keeps the NEWEST scheduled row per
// (post_type, date) and demotes the rest to status='archived' so the
// publish cron skips them but the captions remain auditable.
//
// Idempotent. Safe to re-run.

import { NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const maxDuration = 60;

interface Row {
  id: string;
  post_type: string | null;
  schedule_time: string;
  status: string;
  created_at: string;
}

export async function GET() {
  const sb = createServiceClient();

  const { data: rows } = await sb
    .from("ig_posts")
    .select("id, post_type, schedule_time, status, created_at")
    .in("status", ["scheduled", "pending_approval"])
    .order("created_at", { ascending: false })
    .limit(2000);

  // Group by (post_type, date(schedule_time))
  const byKey = new Map<string, Row[]>();
  for (const r of (rows ?? []) as Row[]) {
    const date = (r.schedule_time ?? "").slice(0, 10);
    const key = `${r.post_type ?? "image"}__${date}`;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key)!.push(r);
  }

  const keep: string[] = [];
  const archive: string[] = [];

  for (const [, group] of byKey) {
    if (group.length === 1) {
      keep.push(group[0].id);
      continue;
    }
    // Prefer existing 'scheduled' over 'pending_approval'; tie-break newest created_at
    const ranked = [...group].sort((a, b) => {
      const aWeight = a.status === "scheduled" ? 1 : 0;
      const bWeight = b.status === "scheduled" ? 1 : 0;
      if (aWeight !== bWeight) return bWeight - aWeight;
      return b.created_at.localeCompare(a.created_at);
    });
    keep.push(ranked[0].id);
    for (const r of ranked.slice(1)) archive.push(r.id);
  }

  let archived = 0;
  let promoted = 0;

  // Demote duplicates to 'draft' (the original CHECK constraint never
  // allowed 'archived', so we use 'draft' which is universally
  // accepted). The publish cron only picks up 'scheduled' rows, so
  // drafts are effectively shelved without losing the captions.
  for (const id of archive) {
    const { error } = await sb
      .from("ig_posts")
      .update({ status: "draft", error: "duplicate_cleanup" })
      .eq("id", id);
    if (!error) archived += 1;
  }

  // Make sure every survivor that's still pending_approval is promoted
  for (const id of keep) {
    const r = (rows ?? []).find((x) => x.id === id) as Row | undefined;
    if (r?.status === "pending_approval") {
      const { error } = await sb
        .from("ig_posts")
        .update({ status: "scheduled" })
        .eq("id", id);
      if (!error) promoted += 1;
    }
  }

  return NextResponse.json({
    ok: true,
    examined: (rows ?? []).length,
    distinct_groups: byKey.size,
    archived,
    promoted_to_scheduled: promoted,
    kept: keep.length,
  });
}

// Read-only auto-poster diagnostic.
//
// George reports posts haven't gone out for ~5 days. This endpoint
// answers, in one call:
//   - is the global crons_paused flag set? (if yes → why)
//   - are IG_ACCESS_TOKEN / IG_BUSINESS_ID env vars present?
//   - what is each post-stream's queue depth + last-success timestamp?
//   - how many photos / videos are sitting unused in the libraries?
//   - what do the last cron observer rows say for each posting cron?
//
// Pure read. No writes. No external API calls. Safe to invoke anytime.

import { NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase-server";

export const runtime = "nodejs";
export const maxDuration = 60;

const POSTING_CRONS = [
  "instagram-publish",
  "instagram-publish-reel",
  "instagram-stories",
  "tiktok-mirror",
  "facebook-mirror",
  "blog-to-social",
  "linkedin-blog-digest",
  "linkedin-company-amplify",
  "instagram-health-check",
];

interface CronTrace {
  name: string;
  last_start_at: string | null;
  last_end_at: string | null;
  last_outcome: string | null;
  last_skip_reason: string | null;
  last_error: string | null;
  run_count_7d: number;
}

async function getCronTrace(
  sb: ReturnType<typeof createServiceClient>,
  name: string,
): Promise<CronTrace> {
  // Settings keys are `cron_start_<runId>` and `cron_end_<runId>`; the
  // value is JSON containing { name, ... }. We can't index by name on
  // an opaque JSON value cheaply — but the volume is bounded by the
  // 21-day prune so a full pull is ~1k-2k rows max.
  const { data: rows } = await sb
    .from("settings")
    .select("key, value, updated_at")
    .or(`key.like.cron_start_%,key.like.cron_end_%`)
    .gte("updated_at", new Date(Date.now() - 7 * 86400 * 1000).toISOString())
    .order("updated_at", { ascending: false })
    .limit(2000);

  type Row = { key: string; value: string; updated_at: string };
  let lastStart: Row | null = null;
  let lastEnd: Row | null = null;
  let lastOutcome: string | null = null;
  let lastSkipReason: string | null = null;
  let lastError: string | null = null;
  let runCount = 0;

  for (const r of (rows ?? []) as Row[]) {
    let parsed: any = null;
    try {
      parsed = typeof r.value === "string" ? JSON.parse(r.value) : r.value;
    } catch {
      continue;
    }
    if (parsed?.name !== name) continue;

    if (r.key.startsWith("cron_start_")) {
      runCount += 1;
      if (!lastStart) lastStart = r;
    } else if (r.key.startsWith("cron_end_")) {
      if (!lastEnd) {
        lastEnd = r;
        lastOutcome = parsed.outcome ?? null;
        if (parsed.outcome === "skipped") {
          lastSkipReason =
            parsed.detail?.reason ??
            parsed.detail?.skipped ??
            JSON.stringify(parsed.detail ?? {}).slice(0, 200);
        } else if (parsed.outcome === "error" || parsed.outcome === "exception") {
          lastError =
            parsed.detail?.message ??
            parsed.detail?.error ??
            JSON.stringify(parsed.detail ?? {}).slice(0, 300);
        }
      }
    }
  }

  return {
    name,
    last_start_at: lastStart?.updated_at ?? null,
    last_end_at: lastEnd?.updated_at ?? null,
    last_outcome: lastOutcome,
    last_skip_reason: lastSkipReason,
    last_error: lastError,
    run_count_7d: runCount,
  };
}

async function settingValue(
  sb: ReturnType<typeof createServiceClient>,
  key: string,
): Promise<string | null> {
  const { data } = await sb
    .from("settings")
    .select("value")
    .eq("key", key)
    .maybeSingle();
  return (data?.value as string | null) ?? null;
}

async function countWhere(
  sb: ReturnType<typeof createServiceClient>,
  table: string,
  apply: (q: any) => any,
): Promise<number | null> {
  try {
    const q = sb.from(table).select("id", { count: "exact", head: true });
    const { count, error } = await apply(q);
    if (error) return null;
    return count ?? 0;
  } catch {
    return null;
  }
}

export async function GET() {
  const sb = createServiceClient();

  // 1 — Global pause flag
  const cronsPaused = await settingValue(sb, "crons_paused");
  const cronsPausedReason = await settingValue(sb, "crons_paused_reason");
  const cronsPausedAt = await settingValue(sb, "crons_paused_at");

