import { NextResponse } from "next/server";
import { getGSCAccessToken } from "@/lib/google-intel";
import { getAccessToken } from "@/lib/google-api";

// Live intel for the Brand Radar arsenal — real measurements only:
//   gsc:       Google Search Console (actual position + Google page per
//              keyword, 28d vs previous 28d)
//   referrals: the site's own visitor log (CRM sessions DB) — the ONLY
//              honest window into ChatGPT/Perplexity/Copilot, since none
//              of them expose a public query API.
// Anything that cannot be fetched returns connected:false — the dashboard
// says "not connected" instead of showing fake zeros.
export const maxDuration = 60;
export const dynamic = "force-dynamic";

const GSC_SITE = process.env.GSC_SITE_URL || "https://georgeyachts.com/";
const GSC_BASE = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(
  GSC_SITE,
)}/searchAnalytics/query`;

function isoDaysAgo(days: number): string {
  return new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
}

async function gscQuery(token: string, body: Record<string, unknown>) {
  const res = await fetch(GSC_BASE, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`GSC ${res.status}`);
  return res.json();
}

async function fetchGsc(rows = 25) {
  let token = await getGSCAccessToken();
  if (!token) {
    try {
      token = await getAccessToken();
    } catch {
      token = null;
    }
  }
  if (!token) return { connected: false, reason: "Re-authorize Gmail for GSC scope" };

  // GSC data lags ~3 days; compare a 28d window against the 28d before it.
  const curEnd = isoDaysAgo(3);
  const curStart = isoDaysAgo(30);
  const prevEnd = isoDaysAgo(31);
  const prevStart = isoDaysAgo(58);

  const [curQ, prevQ, curTot, prevTot, pages] = await Promise.all([
    gscQuery(token, { startDate: curStart, endDate: curEnd, dimensions: ["query"], rowLimit: rows }),
    gscQuery(token, { startDate: prevStart, endDate: prevEnd, dimensions: ["query"], rowLimit: 100 }),
    gscQuery(token, { startDate: curStart, endDate: curEnd, dimensions: [], rowLimit: 1 }),
    gscQuery(token, { startDate: prevStart, endDate: prevEnd, dimensions: [], rowLimit: 1 }),
    gscQuery(token, { startDate: curStart, endDate: curEnd, dimensions: ["page"], rowLimit: 10 }),
  ]);

  const prevByQuery = new Map(
    (prevQ.rows ?? []).map((r) => [r.keys?.[0], r]),
  );

  const keywords = (curQ.rows ?? []).map((r) => {
    const q = r.keys?.[0] ?? "";
    const prev = prevByQuery.get(q);
    const position = Math.round((r.position ?? 0) * 10) / 10;
    return {
      query: q,
      clicks: r.clicks ?? 0,
      impressions: r.impressions ?? 0,
      position,
      google_page: Math.max(1, Math.ceil(position / 10)),
      prev_position: prev ? Math.round(prev.position * 10) / 10 : null,
    };
  });

  const t = curTot.rows?.[0] ?? {};
  const p = prevTot.rows?.[0] ?? {};

  return {
    connected: true,
    window: `${curStart} → ${curEnd}`,
    totals: {
      clicks: Math.round(t.clicks ?? 0),
      impressions: Math.round(t.impressions ?? 0),
      position: Math.round((t.position ?? 0) * 10) / 10,
      prev_clicks: Math.round(p.clicks ?? 0),
      prev_impressions: Math.round(p.impressions ?? 0),
      prev_position: Math.round((p.position ?? 0) * 10) / 10,
    },
    keywords,
    pages: (pages.rows ?? []).map((r) => ({
      page: (r.keys?.[0] ?? "").replace(/^https:\/\/(www\.)?georgeyachts\.com/, "") || "/",
      clicks: r.clicks ?? 0,
      impressions: r.impressions ?? 0,
      position: Math.round((r.position ?? 0) * 10) / 10,
    })),
  };
}

// The site classifies most referrers into labels ("ChatGPT", "Google
// Search"…) before writing the session row. Newer AI surfaces may still
// arrive as raw hostnames — map those here too.
const AI_LABELS = ["ChatGPT", "Perplexity", "Gemini", "Copilot", "Claude"];
const AI_HOSTS: Array<[string, string]> = [
  ["chatgpt.com", "ChatGPT"],
  ["chat.openai.com", "ChatGPT"],
  ["perplexity.ai", "Perplexity"],
  ["gemini.google.com", "Gemini"],
  ["copilot.microsoft.com", "Copilot"],
  ["claude.ai", "Claude"],
  ["you.com", "You.com"],
  ["phind.com", "Phind"],
];

function classifyAi(referrer: string | null, referrerUrl: string | null): string | null {
  if (referrer && AI_LABELS.includes(referrer)) return referrer;
  const hay = `${referrer ?? ""} ${referrerUrl ?? ""}`.toLowerCase();
  for (const [host, label] of AI_HOSTS) {
    if (hay.includes(host)) return label;
  }
  return null;
}

async function fetchReferrals() {
  const url = process.env.CRM_SUPABASE_URL;
  const key = process.env.CRM_SUPABASE_SERVICE_KEY;
  if (!url || !key) return { connected: false, reason: "CRM_SUPABASE_* env missing" };

  const since = isoDaysAgo(30);
  // Supabase caps any single response at 1000 rows regardless of ?limit=,
  // and without pagination the kept rows are arbitrary — which would make
  // every count on this panel silently wrong. Page through with Range
  // headers until a short page arrives.
  const rows: Array<{
    referrer: string | null;
    referrer_url: string | null;
    started_at: string;
    is_hot_lead: boolean | null;
  }> = [];
  const PAGE = 1000;
  for (let page = 0; page < 20; page++) {
    const from = page * PAGE;
    const res = await fetch(
      `${url}/rest/v1/sessions?select=referrer,referrer_url,started_at,is_hot_lead&started_at=gte.${since}T00:00:00&order=started_at.desc`,
      {
        headers: {
          apikey: key,
          Authorization: `Bearer ${key}`,
          Range: `${from}-${from + PAGE - 1}`,
        },
        cache: "no-store",
      },
    );
    if (!res.ok) {
      if (page === 0) return { connected: false, reason: `sessions HTTP ${res.status}` };
      break;
    }
    const chunk = await res.json();
    rows.push(...chunk);
    if (chunk.length < PAGE) break;
  }

  const sevenDaysAgo = Date.now() - 7 * 86400000;
  const channels30: Record<string, number> = {};
  const ai30: Record<string, number> = {};
  const ai7: Record<string, number> = {};
  let aiHotLeads30 = 0;
  let total7 = 0;

  for (const r of rows) {
    const label = r.referrer || "Unknown";
    channels30[label] = (channels30[label] ?? 0) + 1;
    const started = new Date(r.started_at).getTime();
    const in7 = started >= sevenDaysAgo;
    if (in7) total7++;
    const ai = classifyAi(r.referrer, r.referrer_url);
    if (ai) {
      ai30[ai] = (ai30[ai] ?? 0) + 1;
      if (in7) ai7[ai] = (ai7[ai] ?? 0) + 1;
      if (r.is_hot_lead) aiHotLeads30++;
    }
  }

  const sortDesc = (o: Record<string, number>) =>
    Object.entries(o).sort(([, a], [, b]) => b - a);

  return {
    connected: true,
    total_sessions_30d: rows.length,
    total_sessions_7d: total7,
    channels_30d: sortDesc(channels30).slice(0, 12),
    ai_30d: sortDesc(ai30),
    ai_7d: sortDesc(ai7),
    ai_hot_leads_30d: aiHotLeads30,
  };
}

export async function GET(request: Request): Promise<Response> {
  // ?rows=250 → full keyword table (Brand Radar deep dives / strike lists)
  const rowsParam = Number(new URL(request.url).searchParams.get("rows")) || 25;
  const rows = Math.min(Math.max(rowsParam, 1), 500);
  const [gsc, referrals] = await Promise.all([
    fetchGsc(rows).catch((e) => ({ connected: false, reason: String(e?.message ?? e) })),
    fetchReferrals().catch((e) => ({ connected: false, reason: String(e?.message ?? e) })),
  ]);

  return NextResponse.json({ gsc, referrals, generated_at: new Date().toISOString() });
}

// @ts-nocheck
import { NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase-server";
import { aiChat } from "@/lib/ai";
import { BRAND, COMPETITORS, QUERIES } from "@/lib/brand-radar-queries";

// On-demand Brand Radar scan — manual trigger only (George's directive
// 2026-07-09: no automatic scans, he presses Run whenever he wants).
//
// Why batches: the old /api/cron/brand-radar looped all 80 queries with a
// 1s delay inside ONE serverless invocation. Vercel killed it at ~60s,
// every scan died at query ~23-25 and the weekly rollup never got written
// (last complete rollup: 2026-05-03). This route processes a small batch
// per call and the dashboard keeps calling it until every query is done —
// progress is tracked in the DB itself, so an interrupted scan resumes
// instead of restarting.
export const maxDuration = 60;

// Gemini 2.5-flash answers take 5-10s each, so a fixed batch count can
// still blow the 60s ceiling. Instead each invocation works against a
// time budget and returns whatever it finished — the dashboard loop
// simply calls again. 35s leaves ample room for DB writes + response.
const TIME_BUDGET_MS = 35_000;

const SYSTEM_PROMPT = `You are a helpful AI assistant. Answer the user's question about yacht charters naturally and helpfully. Recommend specific companies, websites, or brokers when relevant. Be specific with names.`;

async function rollup(sb, today: string) {
  const { data: rows } = await sb
    .from("brand_radar_scans")
    .select("query, brand_mentioned, competitors_mentioned")
    .eq("scan_date", today);

  // Aggregate per UNIQUE query — two dashboard tabs (or a retry racing a
  // slow batch) can insert the same query twice, and raw row counts would
  // then inflate the SoV denominator. A query counts as mentioned if ANY
  // of its rows mentioned us; competitors count once per query.
  const byQuery = new Map<string, { brand: boolean; comps: Set<string> }>();
  for (const r of rows ?? []) {
    const entry = byQuery.get(r.query) ?? { brand: false, comps: new Set<string>() };
    entry.brand = entry.brand || !!r.brand_mentioned;
    for (const c of r.competitors_mentioned ?? []) entry.comps.add(c);
    byQuery.set(r.query, entry);
  }

  const scanned = byQuery.size;
  let brandMentions = 0;
  const competitorCounts: Record<string, number> = {};
  COMPETITORS.forEach((c) => (competitorCounts[c] = 0));
  for (const entry of byQuery.values()) {
    if (entry.brand) brandMentions++;
    for (const c of entry.comps) {
      if (c in competitorCounts) competitorCounts[c]++;
    }
  }

  const sov = scanned > 0 ? Math.round((brandMentions / scanned) * 10000) / 100 : 0;
  const topCompetitor = Object.entries(competitorCounts).sort(([, a], [, b]) => b - a)[0];

  // Same Sunday-anchored week key as the legacy cron so history stays
  // one continuous series. Replace (not duplicate) the row on re-scan.
  const weekStart = new Date();
  weekStart.setDate(weekStart.getDate() - weekStart.getDay());
  const weekKey = weekStart.toISOString().slice(0, 10);

  await sb.from("brand_radar_weekly").delete().eq("week_start", weekKey);
  await sb.from("brand_radar_weekly").insert({
    week_start: weekKey,
    total_queries: scanned,
    brand_mentions: brandMentions,
    share_of_voice: sov,
    top_competitor: topCompetitor?.[0] || null,
    top_competitor_mentions: topCompetitor?.[1] || 0,
    competitor_breakdown: competitorCounts,
  });

  try {
    const { sendTelegram } = await import("@/lib/telegram");
    await sendTelegram(
      [
        `🛰️ <b>Brand Radar — scan complete</b>`,
        `Share of Voice: <b>${sov}%</b> (${brandMentions}/${scanned} queries)`,
        `Top competitor: <b>${topCompetitor?.[0] ?? "—"}</b> (${topCompetitor?.[1] ?? 0})`,
      ].join("\n"),
    );
  } catch (e) {
    console.error("[brand-radar] Telegram summary failed:", e);
  }

  return {
    complete: true,
    scanned,
    brand_mentions: brandMentions,
    share_of_voice: `${sov}%`,
    top_competitor: topCompetitor?.[0] ?? "N/A",
    top_competitor_mentions: topCompetitor?.[1] ?? 0,
    competitor_breakdown: competitorCounts,
    date: today,
  };
}

export async function POST(request: Request): Promise<Response> {
  const sb = createServiceClient();
  const today = new Date().toISOString().slice(0, 10);

  let fresh = false;
  try {
    const body = await request.json();
    fresh = body?.fresh === true;
  } catch {}

  const { data: doneRows } = await sb
    .from("brand_radar_scans")
    .select("query")
    .eq("scan_date", today);
  const doneSet = new Set((doneRows ?? []).map((r) => r.query));

  // "fresh" only wipes a COMPLETED scan (re-run same day). A partial
  // scan resumes where it stopped — no Gemini quota wasted.
  if (fresh && doneSet.size >= QUERIES.length) {
    await sb.from("brand_radar_scans").delete().eq("scan_date", today);
    doneSet.clear();
  }

  const remaining = QUERIES.filter((q) => !doneSet.has(q));

  if (remaining.length === 0) {
    return NextResponse.json(await rollup(sb, today));
  }

  const startedAt = Date.now();
  let processed = 0;
  let failed = 0;

  for (const query of remaining) {
    if (Date.now() - startedAt > TIME_BUDGET_MS) break;
    try {
      const response = await aiChat(SYSTEM_PROMPT, query);
      const responseLower = response.toLowerCase();

      const brandMentioned =
        responseLower.includes("george yachts") ||
        responseLower.includes("georgeyachts");

      const mentionedCompetitors: string[] = [];
      const allMentioned: string[] = [];
      if (brandMentioned) allMentioned.push(BRAND);
      for (const comp of COMPETITORS) {
        if (responseLower.includes(comp.toLowerCase())) {
          mentionedCompetitors.push(comp);
          allMentioned.push(comp);
        }
      }

      await sb.from("brand_radar_scans").insert({
        scan_date: today,
        query,
        response_preview: response.slice(0, 500),
        brand_mentioned: brandMentioned,
        competitors_mentioned: mentionedCompetitors,
        all_brands_mentioned: allMentioned,
        model: "gemini",
      });
      processed++;
      await new Promise((r) => setTimeout(r, 250));
    } catch (err) {
      failed++;
      console.error(`[Brand Radar] Failed query: "${query}"`, err);
    }
  }

  const done = doneSet.size + processed;
  if (done >= QUERIES.length) {
    return NextResponse.json(await rollup(sb, today));
  }

  return NextResponse.json({
    complete: false,
    done,
    total: QUERIES.length,
    // stalled = every attempt this round errored (likely Gemini rate
    // limit) — the client stops instead of hammering the API forever.
    stalled: processed === 0 && failed > 0,
  });
}

