    usedSlugs: [...nextRotation.usedSlugs, yachtSlug],
    lastSlug: yachtSlug,
    cycleStartedAt: nextRotation.cycleStartedAt,
    cyclesCompleted: nextRotation.cyclesCompleted,
  };

  return { yachtSlug, yachtName, imageUrl, rotation: updatedRotation };
}

