import { NextResponse } from "next/server";

const SANITY_PROJECT_ID = "ecqr94ey";
const SANITY_DATASET = "production";
const SANITY_API_VERSION = "2023-11-09";

export const dynamic = "force-dynamic";
export const revalidate = 3600; // Cache for 1 hour

export async function GET() {
  try {
    const query = encodeURIComponent(
      '*[_type == "yacht"] | order(name asc) { name, "slug": slug.current, subtitle, length, sleeps, weeklyRatePrice, yachtType, fleetTier, "image": mainImage.asset->url }'
    );

    const res = await fetch(
      `https://${SANITY_PROJECT_ID}.api.sanity.io/v${SANITY_API_VERSION}/data/query/${SANITY_DATASET}?query=${query}`,
      { next: { revalidate: 3600 } }
    );

    if (!res.ok) {
      throw new Error(`Sanity API error: ${res.status}`);
    }

    const data = await res.json();
    const yachts = (data.result || []).map((y: Record<string, unknown>) => {
      // Determine type from name prefix
      const name = (y.name as string) || "";
      let type = "Motor";
      if (name.startsWith("S/CAT") || name.startsWith("P/CAT")) type = "Catamaran";
      else if (name.startsWith("S/Y")) type = "Sailing";
      else if (name.startsWith("M/Y")) type = "Motor";
      else if (name.startsWith("P/CAT")) type = "Power Cat";

      return {
        name,
        slug: y.slug,
        subtitle: y.subtitle,
        length: y.length,
        sleeps: parseInt(String(y.sleeps || "0")) || 0,
        price: y.weeklyRatePrice || "",
        tier: y.fleetTier || "private",
        type,
        image: y.image || null,
      };
    });

    return NextResponse.json({ yachts, count: yachts.length });
  } catch (error) {
    console.error("[Fleet API] Error:", error);
    return NextResponse.json({ yachts: [], count: 0, error: "Failed to fetch fleet" }, { status: 500 });
  }
}

// /api/gmail/archive — remove INBOX label from a Gmail message (archive).
// Companion to /api/gmail/trash and /api/gmail/star.

import { NextRequest, NextResponse } from "next/server";
import { gmailFetch } from "@/lib/google-api";

export async function POST(request: NextRequest) {
  try {
    const { messageId } = await request.json();

    if (!messageId) {
      return NextResponse.json(
        { error: "Missing messageId" },
        { status: 400 },
      );
    }

    const res = await gmailFetch(`/messages/${messageId}/modify`, {
      method: "POST",
      body: JSON.stringify({
        addLabelIds: [],
        removeLabelIds: ["INBOX"],
      }),
    });

    if (!res.ok) {
      const text = await res.text();
      return NextResponse.json({ error: text }, { status: res.status });
    }

    return NextResponse.json({ success: true });
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "Unknown error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createServiceClient } from "@/lib/supabase-server";
import { sendTelegram } from "@/lib/telegram";
import { aiChat } from "@/lib/ai";
import { detectAutoReply } from "@/lib/auto-reply";
import { detectWarmup } from "@/lib/email-warmup-detector";
import { createNotification } from "@/lib/notifications";

interface ClassifyRequest {
  messageId: string;
  from: string;
  subject: string;
  body: string;
  headers?: Record<string, string>;
}

interface ClassifyResult {
  classification: "HOT" | "WARM" | "COLD" | "NEUTRAL";
  reason: string;
  suggested_response: string;
}

const CLASSIFICATION_PROMPT = `You are an AI assistant for George Yachts, a luxury yacht brokerage. Classify the following email reply based on the sender's level of interest in partnership or yacht services.

CLASSIFICATION RULES:
- HOT: Sender explicitly wants to proceed, book a call, sign a partnership, or make a purchase decision. Shows strong urgency.
- WARM: Sender is interested, asking questions, requesting more info, or engaging positively but not yet committing.
- COLD: Sender is politely declining, asking to be removed, saying not interested, or giving a vague non-committal response.
- NEUTRAL: Auto-replies, out-of-office messages, newsletters, or messages unrelated to business.

Respond ONLY with valid JSON in this exact format:
{
  "classification": "HOT" | "WARM" | "COLD" | "NEUTRAL",
  "reason": "Brief explanation of why this classification was chosen",
  "suggested_response": "A short suggested reply George could send back"
}

EMAIL:
From: {FROM}
Subject: {SUBJECT}
Body:
{BODY}`;

async function classifyWithAI(email: ClassifyRequest): Promise<ClassifyResult> {
  const prompt = CLASSIFICATION_PROMPT
    .replace("{FROM}", email.from)
    .replace("{SUBJECT}", email.subject)
    .replace("{BODY}", email.body.slice(0, 3000)); // Limit body length

  const content = await aiChat(
    "You classify emails for a luxury yacht brokerage. Respond only with valid JSON.",
    prompt
  );

  // Extract JSON from response. Be forgiving: on any parse failure, fall
  // back to NEUTRAL so the caller doesn't 500 (which previously caused
  // the 5-min poll to hammer the same message forever).
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    return {
      classification: "NEUTRAL",
      reason: "AI returned non-JSON content — defaulted to NEUTRAL",
      suggested_response: "",
    };
  }
  try {
    return JSON.parse(jsonMatch[0]) as ClassifyResult;
  } catch {
    return {
      classification: "NEUTRAL",
      reason: "AI JSON parse failed — defaulted to NEUTRAL",
      suggested_response: "",
    };
  }
}

export async function POST(request: NextRequest) {
  try {
    const { messageId, from, subject, body, headers }: ClassifyRequest =
      await request.json();

    if (!messageId || !from) {
      return NextResponse.json(
        { error: "Missing required fields: messageId, from" },
        { status: 400 }
      );
    }

    const sb = createServiceClient();

    // Check if already classified
    const { data: existing } = await sb
      .from("email_classifications")
      .select("*")
      .eq("message_id", messageId)
      .single();

    if (existing) {
      return NextResponse.json(existing);
    }

    // Belt-and-suspenders warmup gate. The cron poller already runs
    // detectWarmup() before reaching here, but this route is also
    // called directly from the dashboard EmailClient — without this
    // gate, manually clicking "Classify" on a warmup that slipped
    // past would (a) call the LLM for nothing, (b) fire a HOT
    // Telegram, (c) move the pipeline. Same return shape as the
    // auto-reply branch so the dashboard renders cleanly.
    const warmupCheck = detectWarmup({
      from,
      subject,
      body,
      headers: headers ?? {},
    });
    if (warmupCheck.isWarmup) {
      const neutralResult: ClassifyResult = {
        classification: "NEUTRAL",
        reason: `Warmup email detected (${warmupCheck.service ?? "generic"} · ${warmupCheck.reason ?? "—"}) — ignored.`,
        suggested_response: "",
      };
      await sb.from("email_classifications").upsert({
        message_id: messageId,
        contact_id: null,
        classification: neutralResult.classification,
        reason: neutralResult.reason,
        suggested_response: neutralResult.suggested_response,
      });
      return NextResponse.json(neutralResult);
    }

    // Short-circuit auto-replies / out-of-office BEFORE spending AI credits
    // or touching pipeline stages. The follow-up sequence must continue
    // as if this email had never arrived.
    const autoCheck = detectAutoReply(subject, body, headers);
    if (autoCheck.isAutoReply) {
      const neutralResult: ClassifyResult = {
        classification: "NEUTRAL",
        reason: `Auto-reply detected (${autoCheck.reason}) — follow-up sequence will continue.`,
        suggested_response: "",
      };

      await sb.from("email_classifications").upsert({
        message_id: messageId,
        contact_id: null,
        classification: neutralResult.classification,
        reason: neutralResult.reason,
        suggested_response: neutralResult.suggested_response,
      });

      return NextResponse.json(neutralResult);
    }

    // Classify with AI
    const result = await classifyWithAI({ messageId, from, subject, body });

    // Extract sender email
    const emailMatch = from.match(/<([^>]+)>/) ?? [null, from];
    const senderEmail = (emailMatch[1] ?? "").toLowerCase().trim();

    // Try to find matching contact
    let contactId: string | null = null;
    if (senderEmail) {
      const { data: contact } = await sb
        .from("contacts")
        .select("id")
        .ilike("email", senderEmail)
        .single();
      contactId = contact?.id ?? null;
    }

    // Save classification
    await sb.from("email_classifications").upsert({
      message_id: messageId,
      contact_id: contactId,
      classification: result.classification,
      reason: result.reason,
      suggested_response: result.suggested_response,
    });

    // 2026-05-14 — Boss directive: WARM Lead Reply Telegram pings are
    // noise. WARM Telegram alert removed; HOT kept (with the reason
    // stripped 2026-05-15 in a follow-up).
    //
    // 2026-05-15 (later) — Boss reiterated that he doesn't want HOT
    // Telegram alerts either ("σου είπα ότι δε θέλω να μου έρχονται"
    // after a 🔴 HOT Lead Reply Telegram fired on calendar invites +
