import { updateRequest, deleteRequest, addNote } from "@/lib/helm-admin";

export const runtime = "nodejs";

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

const HELM_STATUSES = new Set([
  "new", "drafted", "sent", "in_conversation", "negotiating", "won", "lost",
]);

const REQUEST_TYPES = new Set(["direct_client", "travel_agent"]);

const ALLOWED_FIELDS = new Set([
  "status",
  "client_name", "client_title", "client_surname", "client_is_family",
  "client_email", "client_whatsapp",
  "brief", "occasion", "party_size",
  "dates_from", "dates_to", "area",
  "budget", "special_requests",
  "supplier_raw",
  "mode", "no_myba", "show_ghost_credit",
  "request_type", "central_agency_email",
  "won_reason", "lost_reason",
  "follow_up_at",
  "review_draft",
]);

export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const body = await req.json().catch(() => null);
  if (!body || typeof body !== "object") {
    return NextResponse.json({ error: "bad-json" }, { status: 400 });
  }

  // A standalone note append (channel 'note') — no field change.
  if (typeof body.note === "string" && body.note.trim() && Object.keys(body).length === 1) {
    try {
      await addNote(id, body.note.trim());
      return NextResponse.json({ ok: true });
    } catch (e) {
      return NextResponse.json({ error: (e as Error).message }, { status: 500 });
    }
  }

  if (body.status && !HELM_STATUSES.has(body.status)) {
    return NextResponse.json({ error: `invalid status: ${body.status}` }, { status: 400 });
  }
  if (body.request_type && !REQUEST_TYPES.has(body.request_type)) {
    return NextResponse.json({ error: `invalid request_type: ${body.request_type}` }, { status: 400 });
  }

  const patch: Record<string, unknown> = {};
  for (const k of Object.keys(body)) {
    if (ALLOWED_FIELDS.has(k)) patch[k] = body[k];
  }
  if (Object.keys(patch).length === 0) {
    return NextResponse.json({ error: "no-allowed-fields" }, { status: 400 });
  }

  try {
    const request = await updateRequest(id, patch);
    // If a note also rode along with the field change, append it too.
    if (typeof body.note === "string" && body.note.trim()) {
      await addNote(id, body.note.trim());
    }
    return NextResponse.json({ ok: true, request });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  try {
    const result = await deleteRequest(id);
    return NextResponse.json(result);
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

// POST /api/helm/:id/scan-yachts — Phase 1 of the two-phase picker (2026-07-18).
// Given ONE supplier email, return just the list of yacht TITLES (name + a short
// recognisable line) so George ticks the ones he wants before any heavy detailed
// extraction runs. Tiny output → never truncates, even for a 12-yacht email.
// Reads nothing, saves nothing — pure scan.

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { getRequest } from "@/lib/helm-admin";
import { scanSupplierYachts } from "@/lib/helm/extract";

export const runtime = "nodejs";
export const maxDuration = 60;

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const r = await getRequest(id);
  if (!r) return NextResponse.json({ error: "not-found" }, { status: 404 });

  const body = await req.json().catch(() => ({}));
  // useImported → scan the supplier email(s) already imported from Gmail (their
  // brochures are already transcribed into supplier_raw). Otherwise a fresh paste.
  const useImported = body?.useImported === true;
  const text = (useImported ? (r.supplier_raw ?? "") : (body?.text ?? "")).toString().trim();
  if (!text) {
    return NextResponse.json(
      { error: useImported ? "No supplier emails imported yet — import them from Gmail below first." : "Paste the supplier email first." },
      { status: 400 },
    );
  }

  try {
    const yachts = await scanSupplierYachts(text);
    if (!yachts.length) {
      return NextResponse.json({ error: "No yachts found in this email. Check the text and try again." }, { status: 400 });
    }
    return NextResponse.json({ ok: true, yachts });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

// POST /api/helm/:id/send — send the proposal email (with the generated PDF
// attached) via Gmail. Triggered ONLY by George's explicit confirm in the UI;
// never auto-sends. Threads the message, logs an outbound helm_message,
// advances the request to Sent, and sets follow_up_at = now + 4 days.

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { getRequest, markRequestSent, logHelmMessage } from "@/lib/helm-admin";
import { subjectWithRef } from "@/lib/helm/refcode";
import { proposalToken } from "@/lib/helm/proposal-token";
import { downloadProposalPdf } from "@/lib/helm/storage";
import { sendHelmEmail } from "@/lib/helm/gmail-send";
import { PARTNERSHIP_PDF_BASE64, PARTNERSHIP_PDF_FILENAME } from "@/lib/helm/partnership-pdf.generated";
import { addSubscribers } from "@/lib/newsletter-proxy";

export const runtime = "nodejs";
export const maxDuration = 60;

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const r = await getRequest(id);
  if (!r) return NextResponse.json({ error: "not-found" }, { status: 404 });

  const body = await req.json().catch(() => ({}));
  // The GY ref rides on the client/agent subject too (George 2026-07-17), and
  // it must survive any manual edit of the subject line — re-applied here,
  // idempotently, right before the email actually goes out.
  const subject = subjectWithRef((body?.subject ?? r.email_subject ?? "").trim(), r.created_at);
  const emailBody = (body?.body ?? r.email_intro ?? "").trim();
  const to = (r.client_email ?? "").trim();

  // Guards (server-side; the UI also disables the button).
  if (!to) return NextResponse.json({ error: "No client email on this request — add one before sending." }, { status: 400 });
  if (!r.proposal_pdf_path) return NextResponse.json({ error: "Generate the proposal PDF before sending." }, { status: 400 });
  if (!emailBody) return NextResponse.json({ error: "The email body is empty — write/approve a draft first." }, { status: 400 });

  try {
    const isAgent = r.request_type === "travel_agent";
    type Att = { filename: string; mimeType: string; base64: string };
    const attachments: Att[] = [];
    let finalBody = emailBody;

    if (isAgent) {
      // Travel agents get the WHITE-LABEL proposal PDF to forward, plus the
      // partnership / commission program PDF. (Agents don't get the
      // George-branded magazine.)
      const pdf = await downloadProposalPdf(r.proposal_pdf_path);
      attachments.push({ filename: "Charter_Proposal.pdf", mimeType: "application/pdf", base64: Buffer.from(pdf).toString("base64") });
      attachments.push({ filename: PARTNERSHIP_PDF_FILENAME, mimeType: "application/pdf", base64: PARTNERSHIP_PDF_BASE64 });
    } else {
      // Direct client: NO PDF, ever (George 2026-07-18 — "το PDF το βγάζεις
      // τελείως"). The private online magazine is the whole deliverable and it
      // travels as a LINK. Guarantee the link is in the body even after George
      // rewrites the AI draft by hand — he only ever presses Send.
      // Always the clean custom domain for a CLIENT link, never the raw
      // *.vercel.app origin George may be browsing from (2026-07-18).
      const origin = process.env.NEXT_PUBLIC_SITE_URL || "https://command.georgeyachts.com";
      const salonUrl = `${origin}/p/${proposalToken(id)}`;
      if (!finalBody.includes("/p/")) {
        finalBody = `${finalBody.replace(/\s+$/, "")}\n\nYour private selection, with the photographs and everything in one place:\n${salonUrl}`;
      }
    }

    const sent = await sendHelmEmail({
      to,
      subject: subject || "Your Greek charter",
      body: finalBody,
      threadId: r.gmail_thread_id || undefined,
      inReplyTo: r.gmail_last_message_id || undefined,
      attachments,
    });

    await markRequestSent(id, {
      gmail_thread_id: sent.threadId,
      gmail_last_message_id: sent.messageId,
      email_subject: subject || "Your Greek charter",
      email_intro: finalBody,
    });
    await logHelmMessage(id, {
      direction: "outbound",
      channel: "email",
      body: finalBody,
      gmail_message_id: sent.messageId,
    });

    // Auto-grow the newsletter audience from every proposal we actually send:
    // a DIRECT CLIENT → "bridge" (clients), a TRAVEL AGENT → "wake" (the agent's
    // own email is in client_email for travel_agent). Best-effort — it never
    // blocks or fails the send, and the proxy de-dupes + records consent source.
    // send_welcome is OFF so we don't fire a second email on top of the proposal.
    let newsletterSync: { ok: boolean; stream: string; added?: number; error?: string } | null = null;
    try {
      const stream = isAgent ? "wake" : "bridge";
      const res = await addSubscribers({ stream, emails: [to], source: "helm_request", send_welcome: false });
      newsletterSync = { ok: true, stream, added: res.added };
    } catch (e) {
      newsletterSync = { ok: false, stream: isAgent ? "wake" : "bridge", error: (e as Error).message };
      console.warn("[helm/send] newsletter auto-add failed:", (e as Error).message);
    }

    return NextResponse.json({ ok: true, messageId: sent.messageId, threadId: sent.threadId, newsletterSync });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

// POST /api/helm/:id/share-link — a time-limited link to the proposal PDF plus
// a ready-to-send WhatsApp message, for sharing by WhatsApp or manually.
// Admin-gated. White-label aware:
//   • direct_client → George-voice message to the client
//   • travel_agent  → B2B note (George → the agent) pointing at the
//     white-labeled PDF the agent forwards to their own client.
// The PDF itself is already white-labeled for travel_agent (unchanged), and the
// signed URL filename is the neutral request id — no George identity leaks.

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { getRequest } from "@/lib/helm-admin";
import { proposalToken } from "@/lib/helm/proposal-token";

export const runtime = "nodejs";

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const r = await getRequest(id);
  if (!r) return NextResponse.json({ error: "not-found" }, { status: 404 });
  if (!r.proposal_pdf_path) {
    return NextResponse.json({ error: "Generate the proposal PDF first." }, { status: 400 });
  }

  try {
    // Tracked redirect link (/p/<token>) instead of the raw signed URL,
    // so we can record a real "open" when the client follows it. The
    // PDF is freshly signed at click time inside that route.
    // Always the clean custom domain for a CLIENT-shared link, never the raw
    // *.vercel.app origin George may be browsing from (2026-07-18).
    const origin = process.env.NEXT_PUBLIC_SITE_URL || "https://command.georgeyachts.com";
    const url = `${origin}/p/${proposalToken(id)}`;
    const isAgent = r.request_type === "travel_agent";
    const title = String(r.client_title || "").trim();
    const surname = String(r.client_surname || "").trim();

    let message: string;
    if (isAgent) {
      // George → agent (B2B). The linked PDF is white-labeled; the agent
      // forwards it as their own to their client.
      message = `Hello — here is the white-label charter proposal you can forward to your client exactly as is:\n${url}`;
    } else {
      const who = surname ? `${title ? title + " " : ""}${surname}` : "there";
      message = `Dear ${who},\n\nHere is your Greek charter proposal:\n${url}\n\nWarmly,\nGeorge`;
    }

    const whatsapp = String(r.client_whatsapp || "").replace(/\D/g, "");
    return NextResponse.json({ ok: true, url, message, whatsapp });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

// GET /api/helm/:id/supplier-replies — every supplier reply that belongs to
// THIS request, matched automatically (2026-07-17, George: "με δυσκολεύει
// πάρα πολύ να βρω ποιο mail πάει πού").
//
// Two matchers, merged:
//   1. The Gmail THREADS bound at inquiry-send time
//      (extraction.supplier_threads — one per recipient).
//   2. A Ref-code sweep: any OTHER inbox mail whose subject carries this
//      request's GYddmmyyhhmm code (covers the supplier who starts a fresh
//      email instead of replying).
// Inbound messages only (our own SENT are filtered out). Each message is
// flagged `imported` when its [gmail:<id>] marker already sits in
// supplier_raw, so the panel shows what is new at a glance.

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { getRequest } from "@/lib/helm-admin";
import { gmailFetch } from "@/lib/google-api";
import { refCode } from "@/lib/helm/refcode";

export const runtime = "nodejs";
export const maxDuration = 60;

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

type GmailMsg = {
  id: string;
  labelIds?: string[];
  snippet?: string;
  payload?: { headers?: { name: string; value: string }[] };
};

function header(m: GmailMsg, name: string): string {
  return (m.payload?.headers || []).find((h) => h.name.toLowerCase() === name.toLowerCase())?.value ?? "";
}

export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const r = await getRequest(id);
  if (!r) return NextResponse.json({ error: "not-found" }, { status: 404 });

  const ex = (r.extraction && typeof r.extraction === "object" ? r.extraction : {}) as Record<string, unknown>;
  const threads = (Array.isArray(ex.supplier_threads) ? ex.supplier_threads : []) as
    { email: string; thread_id: string; message_id: string; at: string }[];
  const supplierRaw = String(r.supplier_raw ?? "");
  const code = refCode((r as { created_at?: string }).created_at);

  type Reply = { id: string; from: string; subject: string; date: string; snippet: string; imported: boolean };
  const groups: { supplier: string; replies: Reply[] }[] = [];
  const seenIds = new Set<string>();

  try {
    // 1) bound threads, ONE group per supplier — a re-sent inquiry binds a
    // second thread to the same address, and those must merge, not duplicate.
    const bySupplier = new Map<string, Reply[]>();
    for (const t of threads) {
      if (!bySupplier.has(t.email)) bySupplier.set(t.email, []);
      const res = await gmailFetch(
        `/threads/${t.thread_id}?format=metadata&metadataHeaders=From&metadataHeaders=Subject&metadataHeaders=Date`,
      );
      if (!res.ok) continue;
      const thread = (await res.json()) as { messages?: GmailMsg[] };
      for (const m of thread.messages || []) {
        const labels = m.labelIds || [];
        if (labels.includes("SENT") || labels.includes("DRAFT")) continue; // ours
        if (seenIds.has(m.id)) continue;
        seenIds.add(m.id);
        bySupplier.get(t.email)!.push({
          id: m.id,
          from: header(m, "From"),
          subject: header(m, "Subject"),
          date: header(m, "Date"),
          snippet: m.snippet || "",
          imported: supplierRaw.includes(`[gmail:${m.id}]`),
        });
      }
    }
    for (const [supplier, replies] of bySupplier) groups.push({ supplier, replies }); // empty => "no reply yet"

    // 2) Ref-code strays (fresh emails quoting the code, not in any bound thread)
    if (code) {
      const q = encodeURIComponent(`"${code}" in:inbox`);
      const res = await gmailFetch(`/messages?q=${q}&maxResults=20`);
      if (res.ok) {
        const list = (await res.json()) as { messages?: { id: string }[] };
        const strays: Reply[] = [];
        for (const s of list.messages || []) {
          if (seenIds.has(s.id)) continue;
          const mres = await gmailFetch(
            `/messages/${s.id}?format=metadata&metadataHeaders=From&metadataHeaders=Subject&metadataHeaders=Date`,
          );
          if (!mres.ok) continue;
          const m = (await mres.json()) as GmailMsg;
          const labels = m.labelIds || [];
          if (labels.includes("SENT") || labels.includes("DRAFT")) continue;
          seenIds.add(m.id);
          strays.push({
            id: m.id,
            from: header(m, "From"),
            subject: header(m, "Subject"),
            date: header(m, "Date"),
            snippet: m.snippet || "",
            imported: supplierRaw.includes(`[gmail:${m.id}]`),
          });
        }
        if (strays.length) groups.push({ supplier: `Ref ${code} (new emails quoting the code)`, replies: strays });
      }
    }

    const newCount = groups.reduce((n, g) => n + g.replies.filter((x) => !x.imported).length, 0);
    return NextResponse.json({ ok: true, code, groups, newCount });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 500 });
  }
}

// POST /api/helm/:id/upload-media — vessel photos + brochure. Admin-gated.
// Hosting split: IMAGES → Cloudinary (web-optimized); BROCHURE PDFs → our own
// Supabase storage (Cloudinary blocks PDF delivery behind a console toggle, so
// PDFs live with us and "just work"). Two request shapes:
//   • multipart/form-data: { file, kind: "photo" | "brochure" } → upload
//   • application/json:     { action: "add-photo-link" | "remove-photo" |
//                             "add-brochure-link" | "remove-brochure", url? }
// Degrades gracefully when Cloudinary is not configured (paste-link still
// works; file upload returns a friendly "not connected" note, never crashes).

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { addVesselPhoto, removeVesselPhoto, setBrochureUrl, setCombinedMedia, appendCombinedExtraUrl, removeCombinedExtraUrl } from "@/lib/helm-admin";
import { isCloudinaryConfigured, uploadToCloudinary } from "@/lib/helm/cloudinary";
import { uploadBrochurePdf, getSignedProposalUrl } from "@/lib/helm/storage";
import { agencyDomainWarning } from "@/lib/helm/media";

export const runtime = "nodejs";
export const maxDuration = 60;

async function adminEmail(): Promise<string | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
  const jar = await cookies();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => jar.getAll(), setAll: () => {} },
  });
  const { data: { user } } = await supabase.auth.getUser();
  return user?.email ?? null;
}

export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const email = await adminEmail();
  if (!email) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const ctype = req.headers.get("content-type") || "";

  // ---- file upload (multipart) → Cloudinary ----
  if (ctype.includes("multipart/form-data")) {
    let form: FormData;
    try { form = await req.formData(); } catch { return NextResponse.json({ error: "bad form" }, { status: 400 }); }
    const file = form.get("file");
    const kind = String(form.get("kind") || "photo");
    // Combined multi-yacht: a per-yacht photo/brochure is tagged with its index.
    const rawIdx = form.get("yacht_index");
    const yachtIndex = rawIdx !== null && rawIdx !== "" ? Number(rawIdx) : null;
    if (!(file instanceof File)) return NextResponse.json({ error: "no file" }, { status: 400 });

    const buf = Buffer.from(await file.arrayBuffer());
    const isPdf = (file.type || "").toLowerCase() === "application/pdf" || /\.pdf$/i.test(file.name || "");

    // BROCHURE PDFs → OUR OWN Supabase storage, INDEPENDENT of Cloudinary.
    // Cloudinary accounts block PDF delivery behind a console security toggle, so
    // hosting the PDF ourselves makes the brochure button "just work" with zero
    // per-account setup (free, permanent signed link). Images stay on Cloudinary
    // below — they deliver fine and keep web-optimization.
    if (isPdf) {
      if (buf.length > 25 * 1024 * 1024) {
        return NextResponse.json({ error: `This PDF is ${(buf.length / 1024 / 1024).toFixed(1)}MB - the upload limit is 25MB. Compress it (macOS Preview: File > Export > Quartz Filter > Reduce File Size) and upload again.` }, { status: 400 });
      }
      try {
        const secureUrl = await uploadBrochurePdf(id, file.name || "brochure", buf);
        if (yachtIndex !== null && Number.isFinite(yachtIndex)) {
          const combined_media = await setCombinedMedia(id, yachtIndex, { brochure_url: secureUrl });
          return NextResponse.json({ ok: true, configured: true, kind: "brochure", yacht_index: yachtIndex, url: secureUrl, combined_media });
        }
        await setBrochureUrl(id, secureUrl);
        return NextResponse.json({ ok: true, configured: true, kind: "brochure", url: secureUrl });
      } catch (e) {
        return NextResponse.json({ error: (e as Error).message }, { status: 500 });
      }
    }

    // IMAGES → Cloudinary (web-optimized delivery; behaviour unchanged).
    if (!isCloudinaryConfigured()) {
      // graceful degrade — never crash the page
      return NextResponse.json({
        ok: false,
        configured: false,
        message: "Cloudinary is not connected yet. Paste an image/brochure link instead, or add CLOUDINARY_URL in Vercel.",
      });
    }
    try {
      const dataUri = `data:${file.type || "application/octet-stream"};base64,${buf.toString("base64")}`;
      const secureUrl = await uploadToCloudinary(dataUri, { folder: `helm/${id}`, resourceType: "auto" });
