"use client";

import { useEffect, useRef, useState } from "react";

type Msg = {
  id: string;
  body: string;
  sender_role: "charterer" | "admin";
  sender_email: string;
  created_at: string;
  pending?: boolean;
  failed?: boolean;
};

// Tighter polling for live-feel parity with /cabin/chat on the
// public site. Cheap: one ~1KB GET every 3s while the tab is
// visible. Belt-and-suspenders alongside the Telegram nudge that
// already fires when a charterer message hits chat.js.
const POLL = 3000;

// Soft two-tone chime to give George the "ping" feedback he asked
// for ("να παίρνω σαν να μου στέλνεις στο WhatsApp") whenever a
// new charterer message arrives while he's looking at the CRM.
function playChime() {
  try {
    const W = window as typeof window & { webkitAudioContext?: typeof AudioContext };
    const Ctx = window.AudioContext || W.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const now = ctx.currentTime;
    const make = (freq: number, start: number, dur: number) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = "sine";
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, now + start);
      g.gain.exponentialRampToValueAtTime(0.18, now + start + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, now + start + dur);
      o.connect(g).connect(ctx.destination);
      o.start(now + start);
      o.stop(now + start + dur + 0.02);
    };
    make(880, 0, 0.14);
    make(1175, 0.14, 0.18);
    setTimeout(() => ctx.close().catch(() => {}), 600);
  } catch { /* decorative */ }
}

function fmt(iso: string) {
  const d = new Date(iso);
  const same = d.toDateString() === new Date().toDateString();
  return same
    ? d.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })
    : d.toLocaleString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
}

export default function AdminChat({ cabinId }: { cabinId: string }) {
  const [messages, setMessages] = useState<Msg[] | null>(null);
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const listRef = useRef<HTMLUListElement>(null);
  const sinceRef = useRef<string | null>(null);

  async function pullInitial() {
    const r = await fetch(`/api/cabins/${cabinId}/chat`);
    const j = await r.json();
    const m: Msg[] = j.messages ?? [];
    setMessages(m);
    if (m.length) sinceRef.current = m[m.length - 1].created_at;
  }

  async function pullIncremental() {
    if (!sinceRef.current) return;
    try {
      const r = await fetch(`/api/cabins/${cabinId}/chat?since=${encodeURIComponent(sinceRef.current)}`);
      if (!r.ok) return;
      const j = await r.json();
      const newM: Msg[] = j.messages ?? [];
      if (newM.length) {
        setMessages((prev) => [...(prev ?? []), ...newM]);
        sinceRef.current = newM[newM.length - 1].created_at;
        // Ping for any incoming charterer message. George's own
        // sends never arrive via polling — they're already in
        // state when the POST resolves — so a "charterer" role
        // here is unambiguously the client typing on the boat.
        const fromCharterer = newM.some((m) => m.sender_role === "charterer");
        if (fromCharterer) {
          playChime();
          if (
            typeof Notification !== "undefined" &&
            Notification.permission === "granted" &&
            document.visibilityState !== "visible"
          ) {
            try {
              const last = newM[newM.length - 1];
              new Notification("New message in Cabin chat", {
                body: (last.body || "").slice(0, 140),
                tag: `cabin-chat-${cabinId}`,
              });
            } catch { /* notification API varies by browser */ }
          }
        }
      }
    } catch {}
  }

  function enableNotifications() {
    if (typeof Notification === "undefined") return;
    if (Notification.permission === "granted") return;
    Notification.requestPermission().catch(() => {});
  }

  useEffect(() => {
    void pullInitial();
    const id = setInterval(() => {
      if (document.visibilityState === "visible") void pullIncremental();
    }, POLL);
    return () => clearInterval(id);
  }, [cabinId]);

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [messages?.length]);

  async function send(e: React.FormEvent) {
    e.preventDefault();
    const body = draft.trim();
    if (!body || sending) return;
    // Browsers require requestPermission() to run inside a real
    // gesture. Piggybacking on the send click is the natural moment
    // — by the time George hits send he's said "I'm using this."
    enableNotifications();
    setSending(true);
    const localId = "local-" + Date.now();
    setMessages((p) => [...(p ?? []), {
      id: localId, body, sender_role: "admin",
      sender_email: "you", created_at: new Date().toISOString(),
      pending: true,
    }]);
    setDraft("");
    try {
      const r = await fetch(`/api/cabins/${cabinId}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ body }),
      });
      const j = await r.json();
      if (r.ok && j.message) {
        setMessages((p) => (p ?? []).map((m) => m.id === localId ? j.message : m));
        sinceRef.current = j.message.created_at;
      } else {
        setMessages((p) => (p ?? []).map((m) => m.id === localId ? { ...m, failed: true } : m));
      }
    } finally {
      setSending(false);
    }
  }

  return (
    <div style={cardStyle}>
      <ul ref={listRef} style={listStyle} aria-live="polite">
        {messages === null && (
          <li style={emptyStyle}>Loading…</li>
        )}
        {messages?.length === 0 && (
          <li style={emptyStyle}><em>No messages yet.</em></li>
        )}
        {messages?.map((m, i) => {
          const isMe = m.sender_role === "admin";
          const prev = i > 0 ? messages[i - 1] : null;
          const grouped = prev && prev.sender_role === m.sender_role &&
            (new Date(m.created_at).getTime() - new Date(prev.created_at).getTime()) < 5 * 60 * 1000;
          return (
            <li key={m.id || i} style={{
              ...msgRowStyle,
              alignItems: isMe ? "flex-end" : "flex-start",
              marginTop: grouped ? 2 : 10,
            }}>
              {!grouped && (
                <span style={whoStyle}>
                  {isMe ? "George (you)" : "Client"} <em style={{ fontStyle: "italic", color: "#9CA3AF", marginLeft: 4 }}>· {fmt(m.created_at)}</em>
                </span>
              )}
              <span style={{
                ...bubbleStyle,
                background: isMe ? "#0D1B2A" : "rgba(201,168,76,0.08)",
                color: isMe ? "#F8F5F0" : "#0D1B2A",
                border: isMe ? "1px solid #0D1B2A" : "1px solid rgba(201,168,76,0.35)",
                opacity: m.pending ? 0.6 : 1,
                borderColor: m.failed ? "#b14a3a" : undefined,
              }}>
                {m.body}
              </span>
            </li>
          );
        })}
      </ul>

      <form onSubmit={send} style={composeStyle}>
        <textarea
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) send(e); }}
          placeholder="Your reply… ⌘+Enter to send"
          rows={2}
          maxLength={8000}
          style={textareaStyle}
        />
        <button type="submit" disabled={sending || !draft.trim()} style={btnStyle}>
          {sending ? "Sending…" : "Send"}
        </button>
      </form>
    </div>
  );
}

