"use client";

import { useState } from "react";

export default function ContentEditor({
  cabinId,
  field,
  title,
  hint,
  initial,
}: {
  cabinId: string;
  field: string;
  title: string;
  hint: string;
  initial: unknown;
}) {
  const [value, setValue] = useState(() => JSON.stringify(initial ?? {}, null, 2));
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);

  async function save() {
    setBusy(true);
    setMsg(null);
    let parsed: unknown;
    try {
      parsed = JSON.parse(value);
    } catch (e) {
      setMsg({ ok: false, text: "Invalid JSON: " + (e as Error).message });
      setBusy(false);
      return;
    }
    try {
      const r = await fetch(`/api/cabins/${cabinId}/content`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ [field]: parsed }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "save-failed");
      setMsg({ ok: true, text: "Saved" });
    } catch (e) {
      setMsg({ ok: false, text: (e as Error).message });
    } finally {
      setBusy(false);
    }
  }

  return (
    <details
      open
      style={{ background: "#fff", border: "1px solid rgba(13,27,42,0.08)" }}
    >
      <summary style={{
        cursor: "pointer", padding: "14px 18px",
        fontFamily: "Georgia, serif", fontSize: 16,
      }}>
        {title}
      </summary>
