      setMsg({ ok: false, text: (e as Error).message });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={card}>
      <header style={hdr}>
        <h3 style={h3}>Sample menu (what the client sees on /cabin/menu)</h3>
        <p style={sub}>
          One section per row (Breakfast, Appetizers, Main Courses, Desserts —
