const primaryBtn: React.CSSProperties = { background: "#0D1B2A", color: "#F8F5F0", border: "1px solid #C9A84C", padding: "10px 18px", fontSize: 10, letterSpacing: 2, textTransform: "uppercase", cursor: "pointer" };
const ghostBtn: React.CSSProperties = { background: "#fff", color: "#0D1B2A", border: "1px solid rgba(13,27,42,0.2)", padding: "9px 14px", fontSize: 10, letterSpacing: 2, textTransform: "uppercase", cursor: "pointer" };

"use client";

// Shared review widget (both Direct Client + Travel Agent, single + combined):
// owner discount, relocation fee, optional total-rounding, and a LIVE preview of
// the exact breakdown so the broker sees every figure before generating. All
// math is computePricing (pricing.ts) - the same engine the PDF uses, so the
// preview is exactly what ships. To round APA/VAT the broker edits their amount
// in the main price fields; to round the final total he uses "Round total".

import { computePricing, type PricingInput } from "@/lib/helm/pricing";

export default function PricingExtras({
  pricing, discount, relocation, override, onChange,
}: {
  pricing: PricingInput;
  discount: string;
  relocation: string;
  override: string;
  onChange: (k: "discount_pct" | "relocation_fee" | "all_in_override", v: string) => void;
}) {
  const pr = computePricing(pricing);
  return (
    <div style={{ marginTop: 12 }}>
      <div style={lbl}>Owner discount · relocation · rounding (optional)</div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 6 }}>
        <Field label="Owner discount %" value={discount} placeholder="e.g. 5" onChange={(v) => onChange("discount_pct", v)} />
        <Field label="Relocation fee" value={relocation} placeholder="e.g. 3360 or TBA" onChange={(v) => onChange("relocation_fee", v)} />
        <Field label="Round total € (optional)" value={override} placeholder="blank = exact" onChange={(v) => onChange("all_in_override", v)} />
      </div>

      <div style={previewBox}>
        <div style={{ fontSize: 10, letterSpacing: 1.5, textTransform: "uppercase", color: "#9CA3AF", marginBottom: 5 }}>Live preview (exactly what the PDF shows)</div>
        <div style={prow}><span>Charter Fee</span><span>{pr.charter_fee_disp || "—"}</span></div>
        {pr.discount_note && <div style={{ color: "#B07A2C", fontWeight: 600, fontSize: 12, margin: "2px 0" }}>{pr.discount_note}</div>}
        {pr.rows.map(([l, a], i) => (
          <div key={i} style={prow}><span>{l}</span><span>{a}</span></div>
        ))}
        {pr.all_in && (
          <div style={{ ...prow, borderTop: "1px solid rgba(13,27,42,0.18)", marginTop: 5, paddingTop: 5, fontWeight: 700, color: "#0D1B2A" }}>
            <span>{pr.all_inclusive ? "All-inclusive" : "Estimated all-in total"}</span><span>{pr.all_in}</span>
          </div>
        )}
        {pr.per_person_4 && <div style={{ fontSize: 11, color: "#6b7280", marginTop: 4 }}>Per guest: {pr.per_person_4} (4) · {pr.per_person_6} (6)</div>}
        <div style={{ fontSize: 10.5, color: "#9CA3AF", marginTop: 5, fontStyle: "italic" }}>
          Round APA/VAT by editing their amount in the fields above; round the final total with &quot;Round total&quot;.
        </div>
      </div>
    </div>
  );
}

function Field({ label, value, placeholder, onChange }: { label: string; value: string; placeholder?: string; onChange: (v: string) => void }) {
  return (
    <label style={{ display: "block" }}>
      <div style={{ fontSize: 10, letterSpacing: 1, textTransform: "uppercase", color: "#9CA3AF" }}>{label}</div>
      <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} inputMode="decimal"
        style={{ width: 150, padding: 7, border: "1px solid rgba(13,27,42,0.2)", fontSize: 13, fontFamily: "inherit", marginTop: 3 }} />
    </label>
  );
}

const lbl: React.CSSProperties = { fontSize: 10, letterSpacing: 1.5, textTransform: "uppercase", color: "#9CA3AF" };
const previewBox: React.CSSProperties = { border: "1px solid rgba(13,27,42,0.12)", background: "rgba(201,168,76,0.06)", padding: "8px 12px", marginTop: 10, borderRadius: 2 };
const prow: React.CSSProperties = { display: "flex", justifyContent: "space-between", fontSize: 12.5, color: "#374151", padding: "2px 0" };

"use client";

// Split-season proration calculator (broker method). When a yacht is quoted
// with seasonal weekly rates and the charter straddles a season boundary, the
// broker turns each weekly rate into a daily rate (weekly / 7, rounded) and
// charters the days in each season separately. Example:
//   June 19,000/wk -> 2,700/day x 5 + July 21,000/wk -> 3,000/day x 2 = 19,500.
// All arithmetic is in pricing.ts (suggestDailyRate / prorateSeasonsTotal).
// The broker sets the daily rate + day count; pressing Apply writes the total
// into that yacht's charter fee. Single fixed rate -> this is never shown.

import { useState } from "react";
import { suggestDailyRate, prorateSeasonsTotal } from "@/lib/helm/pricing";

type Row = { label: string; weekly: number; daily: string; days: string };

export default function SeasonProration({
  rates, onApply,
}: {
  rates: { label: string; fee: number }[];
  onApply: (total: number) => void;
}) {
  const [open, setOpen] = useState(false);
  const [rows, setRows] = useState<Row[]>(() =>
    rates.map((r) => ({ label: r.label, weekly: r.fee, daily: String(suggestDailyRate(r.fee)), days: "" })),
  );

  const set = (i: number, k: "daily" | "days", v: string) =>
    setRows((rs) => rs.map((r, idx) => (idx === i ? { ...r, [k]: v } : r)));

  const totalDays = rows.reduce((s, r) => s + (Number(r.days) || 0), 0);
  const total = prorateSeasonsTotal(rows.map((r) => ({ daily: r.daily, days: r.days })));
  const fmt = (n: number) => "€ " + n.toLocaleString("en-US");

  if (!open) {
    return (
      <button type="button" onClick={() => setOpen(true)} style={linkBtn}>
        Spans two seasons? Split by day →
      </button>
    );
  }

  return (
    <div style={box}>
      <div style={{ fontSize: 11.5, color: "#374151", marginBottom: 8 }}>
        Daily = weekly ÷ 7 (rounded; edit if you round differently). A charter week is normally 7 days - allocate them across the seasons by the actual dates.
      </div>
      {rows.map((r, i) => (
        <div key={i} style={rowS}>
          <span style={{ flex: 1, fontSize: 12.5, color: "#1f2937" }}>{r.label}</span>
          <span style={{ fontSize: 12, color: "#6b7280", width: 110, textAlign: "right" }}>{fmt(r.weekly)}/wk</span>
          <label style={lbl}>day €
            <input value={r.daily} onChange={(e) => set(i, "daily", e.target.value)} inputMode="numeric" style={miniInput} />
          </label>
          <label style={lbl}>×
            <input value={r.days} onChange={(e) => set(i, "days", e.target.value)} inputMode="numeric" placeholder="days" style={{ ...miniInput, width: 48 }} />
          </label>
          <span style={{ width: 92, textAlign: "right", fontSize: 12.5, color: "#1f2937" }}>
            = {fmt((Number(r.daily) || 0) * (Number(r.days) || 0))}
          </span>
        </div>
      ))}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 8, flexWrap: "wrap", gap: 8 }}>
        <span style={{ fontSize: 12, color: totalDays === 7 ? "#3A6B47" : "#B07A2C" }}>
          Total days: <b>{totalDays}</b>{totalDays !== 7 ? " (a charter week is usually 7)" : ""} · Charter fee: <b>{fmt(total)}</b>
        </span>
        <span style={{ display: "flex", gap: 8 }}>
          <button type="button" disabled={total <= 0} onClick={() => onApply(total)} style={{ ...applyBtn, opacity: total > 0 ? 1 : 0.5 }}>
            Use {fmt(total)} as charter fee
          </button>
          <button type="button" onClick={() => setOpen(false)} style={closeBtn}>Close</button>
        </span>
      </div>
    </div>
  );
}

const linkBtn: React.CSSProperties = { background: "none", border: "none", color: "#0D1B2A", fontSize: 12, textDecoration: "underline", cursor: "pointer", padding: "4px 0", marginTop: 4 };
const box: React.CSSProperties = { border: "1px solid rgba(13,27,42,0.15)", background: "rgba(13,27,42,0.02)", padding: "10px 12px", marginTop: 8, borderRadius: 2 };
const rowS: React.CSSProperties = { display: "flex", alignItems: "center", gap: 8, padding: "3px 0", flexWrap: "wrap" };
const lbl: React.CSSProperties = { display: "inline-flex", alignItems: "center", gap: 4, fontSize: 12, color: "#6b7280" };
const miniInput: React.CSSProperties = { width: 72, padding: 5, border: "1px solid rgba(13,27,42,0.2)", fontSize: 12.5, fontFamily: "inherit" };
const applyBtn: React.CSSProperties = { background: "#0D1B2A", color: "#F8F5F0", border: "1px solid #C9A84C", padding: "6px 12px", fontSize: 10, letterSpacing: 1.5, textTransform: "uppercase", cursor: "pointer" };
const closeBtn: React.CSSProperties = { background: "#fff", color: "#6b7280", border: "1px solid rgba(13,27,42,0.2)", padding: "6px 10px", fontSize: 10, letterSpacing: 1.5, textTransform: "uppercase", cursor: "pointer" };

"use client";

// Pipeline pills for a charter request. A sale is non-linear, so George can move
// a request to ANY stage at will (e.g. New -> Lost when a lead calls to cancel).
// Every change asks for confirmation and names both states; moving to Lost/Won
// prompts for an optional reason. The chosen stage is saved and persists.

import { useState } from "react";
import { useRouter } from "next/navigation";

const FLOW = [
  { key: "new",             label: "New" },
  { key: "drafted",         label: "Drafted" },
  { key: "sent",            label: "Sent" },
  { key: "in_conversation", label: "In conversation" },
  { key: "negotiating",     label: "Negotiating" },
  { key: "won",             label: "Won" },
  { key: "lost",            label: "Lost" },
];

export default function StatusTransitions({
  requestId,
  current,
}: {
  requestId: string;
  current: string;
}) {
  const router = useRouter();
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // A sale is non-linear: every OTHER stage is reachable, so George can set any.
  const allowed = new Set(FLOW.filter((s) => s.key !== current).map((s) => s.key));

  async function setStatus(next: string) {
    const from = (current || "—").replace(/_/g, " ").toUpperCase();
    const to = next.replace(/_/g, " ").toUpperCase();
    const ok = confirm(`Move this request from ${from} to ${to}?`);
    if (!ok) return;

    const body: Record<string, unknown> = { status: next };
    if (next === "lost") {
      const reason = prompt("Why was this lost? (optional, helps the pipeline learn)");
      if (reason) body.lost_reason = reason;
    } else if (next === "won") {
      const reason = prompt("Won — any note? (e.g. which yacht, terms)");
      if (reason) body.won_reason = reason;
    }

    setBusy(next);
    setError(null);
    try {
      const r = await fetch(`/api/helm/${requestId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "update-failed");
      router.refresh();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div style={{
      background: "#fff",
      border: "1px solid rgba(13,27,42,0.08)",
      padding: "14px 16px",
      marginTop: 14,
    }}>
      <div style={{ fontSize: 10, letterSpacing: 2.5, textTransform: "uppercase", color: "#6b7280", marginBottom: 4 }}>
        Pipeline
      </div>
      <div style={{ fontSize: 11, color: "#4b5563", fontStyle: "italic", marginBottom: 10 }}>
        Current stage is the gold badge. Click any other stage to move there (you will be asked to confirm). The change is saved and stays.
      </div>
      <ol style={{ listStyle: "none", padding: 0, margin: 0, display: "flex", gap: 8, flexWrap: "wrap" }}>
        {FLOW.map((s) => {
          const isCurrent = s.key === current;
          const enabled = allowed.has(s.key);

          let chipStyle: React.CSSProperties = {
            padding: "8px 14px",
            fontSize: 11,
            letterSpacing: 1.8,
            textTransform: "uppercase",
            fontWeight: isCurrent ? 700 : 400,
            minWidth: 96,
            textAlign: "center",
            border: "1px solid transparent",
            cursor: "default",
            transition: "background 140ms ease, border-color 140ms ease",
          };
          if (isCurrent) {
            chipStyle = { ...chipStyle, background: "#C9A84C", color: "#0D1B2A", borderColor: "#C9A84C" };
          } else if (enabled) {
            chipStyle = {
              ...chipStyle,
              background: "#ffffff", color: "#0D1B2A",
              borderStyle: "dashed", borderColor: "#0D1B2A",
              cursor: busy !== null ? "default" : "pointer",
            };
          } else {
            chipStyle = { ...chipStyle, background: "#ffffff", color: "#9CA3AF", borderColor: "rgba(13,27,42,0.08)" };
          }

          return (
            <li key={s.key}>
              <button
                type="button"
                onClick={() => enabled && setStatus(s.key)}
                disabled={!enabled || busy !== null}
                aria-current={isCurrent ? "step" : undefined}
                title={
                  isCurrent
                    ? `Current status: ${s.label}`
                    : enabled
                      ? `Move to ${s.label} (you'll be asked to confirm)`
                      : `${s.label} — not reachable from here`
                }
                style={chipStyle}
              >
                {busy === s.key ? "…" : s.label}
              </button>
            </li>
          );
        })}
      </ol>
      {error && <p style={{ color: "#b91c1c", fontSize: 12, marginTop: 8 }}>{error}</p>}
    </div>
  );
}

"use client";

// The Helm — SUPPLIER REPLIES, auto-matched to this request (2026-07-17).
// George sends inquiries to five suppliers across three requests and the
// answers used to land as an unsorted pile in his inbox. Now every reply that
// belongs to THIS request appears here by itself (bound Gmail threads + the
// Ref-code sweep), each with one Import button that drops it into the
// supplier text ready for Extract. No more reading whole emails to figure
// out which client they are about.

import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";

type Reply = { id: string; from: string; subject: string; date: string; snippet: string; imported: boolean };
type Group = { supplier: string; replies: Reply[] };

function fmtWhen(dateHeader: string): string {
  const d = new Date(dateHeader);
  if (isNaN(d.getTime())) return dateHeader;
  return d.toLocaleString("en-GB", { weekday: "short", day: "numeric", month: "short", hour: "2-digit", minute: "2-digit", timeZone: "Europe/Athens" });
}

function senderName(from: string): string {
  const m = from.match(/^\s*"?([^"<]+?)"?\s*</);
  return (m ? m[1] : from).trim();
}

export default function SupplierReplies({ requestId }: { requestId: string }) {
  const router = useRouter();
  const [groups, setGroups] = useState<Group[] | null>(null);
  const [code, setCode] = useState("");
  const [newCount, setNewCount] = useState(0);
  const [busy, setBusy] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const load = useCallback(async () => {
    setBusy("load"); setErr(null);
    try {
      const r = await fetch(`/api/helm/${requestId}/supplier-replies`);
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "load failed");
      setGroups(j.groups || []);
      setCode(j.code || "");
      setNewCount(j.newCount || 0);
    } catch (e) { setErr((e as Error).message); } finally { setBusy(null); }
  }, [requestId]);

  useEffect(() => { load(); }, [load]);

  async function importReply(messageId: string) {
    setBusy(messageId); setErr(null);
    try {
      const r = await fetch(`/api/helm/${requestId}/gmail-import`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "import", messageIds: [messageId], readBrochures: true }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "import failed");
      await load();
      router.refresh();
    } catch (e) { setErr((e as Error).message); } finally { setBusy(null); }
  }

  const label: React.CSSProperties = { fontSize: 10, letterSpacing: 2, textTransform: "uppercase", color: "#6b7280", fontWeight: 700 };
  const hasAnything = (groups?.length ?? 0) > 0;

  return (
    <section style={{ background: "#fff", border: "1px solid rgba(13,27,42,0.08)", borderRadius: 2, padding: "14px 16px", marginTop: 14 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
        <span style={label}>Supplier replies · matched to this request</span>
        {newCount > 0 && (
          <span style={{ background: "#C9A84C", color: "#0D1B2A", borderRadius: 999, fontSize: 11, fontWeight: 700, padding: "2px 10px" }}>
            {newCount} new
          </span>
        )}
        {code && <span style={{ fontSize: 11, color: "#9CA3AF" }}>Ref {code}</span>}
        <button type="button" onClick={load} disabled={busy !== null}
          style={{ marginLeft: "auto", background: "none", border: "1px solid rgba(13,27,42,0.2)", borderRadius: 2, padding: "4px 10px", fontSize: 11, cursor: "pointer", color: "#0D1B2A" }}>
          {busy === "load" ? "Checking…" : "Refresh"}
        </button>
      </div>

      {err && <p style={{ color: "#b91c1c", fontSize: 12.5, marginTop: 8 }}>{err}</p>}
      {groups === null && !err && <p style={{ color: "#9CA3AF", fontSize: 12.5, marginTop: 8 }}>Checking your suppliers&apos; threads…</p>}
      {groups !== null && !hasAnything && (
        <p style={{ color: "#9CA3AF", fontSize: 12.5, fontStyle: "italic", marginTop: 8 }}>
          No supplier inquiries sent from this request yet. Send one below (Ask the suppliers) and every reply will appear here by itself.
        </p>
      )}

      {(groups || []).map((g, gi) => (
        <div key={`${g.supplier}-${gi}`} style={{ marginTop: 12 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: "#1f2937" }}>
            {g.supplier}
            {g.replies.length === 0 && <span style={{ color: "#9CA3AF", fontWeight: 400 }}> · no reply yet</span>}
          </div>
          {g.replies.map((m) => (
            <div key={m.id} style={{
              display: "flex", gap: 10, alignItems: "flex-start", padding: "8px 10px", marginTop: 6,
              background: m.imported ? "rgba(58,107,71,0.06)" : "rgba(201,168,76,0.08)", borderRadius: 2,
            }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, color: "#1f2937" }}>
                  <b>{senderName(m.from)}</b> · <span style={{ color: "#6b7280" }}>{fmtWhen(m.date)}</span>
                </div>
                <div style={{ fontSize: 12, color: "#9CA3AF", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {m.snippet}
                </div>
              </div>
              {m.imported ? (
                <span style={{ fontSize: 11, color: "#3A6B47", fontWeight: 700, flexShrink: 0, paddingTop: 3 }}>✓ imported</span>
              ) : (
                <button type="button" onClick={() => importReply(m.id)} disabled={busy !== null}
                  style={{ flexShrink: 0, background: "#0D1B2A", color: "#fff", border: "none", borderRadius: 2, padding: "6px 12px", fontSize: 11, cursor: "pointer" }}>
                  {busy === m.id ? "Importing…" : "Import"}
                </button>
              )}
            </div>
          ))}
        </div>
      ))}
    </section>
  );
}

"use client";

// The two-phase yacht picker (2026-07-18, George's design): a supplier offers
// 12 yachts, he wants 6-7. It lists ONLY the yacht titles → George ticks the
// ones he wants → it extracts full detail (numbers + the brochure content that
// makes the magazine rich) for JUST those and adds them. Repeat per supplier.
//
// TWO sources: the supplier emails he already imported from Gmail (their
// brochures are already transcribed into the record — the primary path), OR a
// fresh pasted email. No more pulling in 26 yachts to hand-exclude 20, and no
// truncation crash on a long multi-yacht email.

import { useState } from "react";

type Scanned = { name: string; line: string; snippet: string };

export default function SupplierYachtPicker({ requestId, hasImported }: { requestId: string; hasImported: boolean }) {
  const [text, setText] = useState("");
  const [scanned, setScanned] = useState<Scanned[] | null>(null);
  const [source, setSource] = useState<"imported" | "pasted" | null>(null);
  const [picked, setPicked] = useState<Set<string>>(new Set());
  const [busy, setBusy] = useState<null | "imported" | "pasted" | "add">(null);
  const [err, setErr] = useState<string | null>(null);
  const [msg, setMsg] = useState<string | null>(null);

  async function scan(from: "imported" | "pasted") {
    if (from === "pasted" && !text.trim()) return;
    setBusy(from); setErr(null); setMsg(null); setScanned(null); setPicked(new Set());
    try {
      const r = await fetch(`/api/helm/${requestId}/scan-yachts`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify(from === "imported" ? { useImported: true } : { text }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "scan failed");
      setScanned(j.yachts as Scanned[]);
      setSource(from);
    } catch (e) { setErr((e as Error).message); } finally { setBusy(null); }
  }

  function toggle(name: string) {
    setPicked((prev) => {
      const n = new Set(prev);
      if (n.has(name)) n.delete(name); else n.add(name);
      return n;
    });
  }
  const allPicked = !!scanned && scanned.length > 0 && picked.size === scanned.length;
  function toggleAll() {
    if (!scanned) return;
    setPicked(allPicked ? new Set() : new Set(scanned.map((y) => y.name)));
  }

  async function add() {
    if (!scanned || picked.size === 0 || !source) return;
    setBusy("add"); setErr(null); setMsg(null);
    try {
      const r = await fetch(`/api/helm/${requestId}/extract-picked`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify(source === "imported" ? { useImported: true, names: [...picked] } : { text, names: [...picked] }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || "add failed");
      setMsg(`Added ${j.added} yacht${j.added === 1 ? "" : "s"} — loading the cards…`);
      // A full reload: adding the first yacht flips the request to combined mode,
      // and the yacht-cards panel is a client component seeded once on mount, so
      // router.refresh() alone would not show the new cards. Reload re-mounts it.
      setTimeout(() => window.location.reload(), 700);
    } catch (e) { setErr((e as Error).message); } finally { setBusy(null); }
  }

  return (
    <section style={card}>
      <div style={cardLabel}>Add yachts from a supplier email</div>
      <p style={{ fontSize: 12.5, color: "#6b7280", lineHeight: 1.6, margin: "0 0 12px" }}>
        See the yacht names, tick the ones you want, and only those are added - with their brochure detail read in for the magazine. Repeat per supplier.
      </p>

      {hasImported && (
        <div style={{ marginBottom: 12 }}>
          <button type="button" onClick={() => scan("imported")} disabled={busy !== null} style={primaryBtn}>
            {busy === "imported" ? "Reading the yachts + brochures…" : "Scan the supplier emails I imported"}
