// src/lib/helm/storage.ts
// Supabase Storage for generated proposal PDFs. Private bucket
// 'helm-proposals' (proposals are confidential); the detail page streams
// them through an admin-gated route, never a public URL.

import { createServiceClient } from "../supabase-server";

export const PROPOSALS_BUCKET = "helm-proposals";

/** Upload (or overwrite) the proposal PDF for a request. Returns the path. */
export async function uploadProposalPdf(
  requestId: string,
  bytes: Uint8Array,
): Promise<string> {
  const db = createServiceClient();
  const path = `${requestId}.pdf`;
  const { error } = await db.storage
    .from(PROPOSALS_BUCKET)
    .upload(path, bytes, { contentType: "application/pdf", upsert: true });
  if (error) throw new Error(`storage upload failed: ${error.message}`);
  return path;
}

/** Download the stored proposal PDF bytes (for the admin-gated stream route). */
export async function downloadProposalPdf(path: string): Promise<Uint8Array> {
  const db = createServiceClient();
  const { data, error } = await db.storage.from(PROPOSALS_BUCKET).download(path);
  if (error || !data) throw new Error(`storage download failed: ${error?.message ?? "no data"}`);
  return new Uint8Array(await data.arrayBuffer());
}

/** Upload a brochure PDF to OUR OWN storage (reuses the private helm-proposals
 *  bucket under a brochures/ prefix) and return a long-lived signed URL.
 *  This is deliberately independent of Cloudinary — Cloudinary accounts block
 *  PDF delivery by a console security toggle, so brochure PDFs live here instead
 *  and "just work" (free, no per-account setup). The link is embedded in the
 *  proposal's gold brochure button; 5 years easily outlives any charter cycle. */
/** Same brochures/<id>/<slug>-<ts>.pdf path scheme used by both the server-side
 *  upload and the browser direct-upload (createBrochureUploadUrl). */
function brochurePath(requestId: string, filename: string): string {
  const slug =
    (filename || "brochure")
      .replace(/\.pdf$/i, "")
      .replace(/[^a-z0-9.-]+/gi, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .toLowerCase()
      .slice(0, 60) || "brochure";
  return `brochures/${requestId}/${slug}-${Date.now().toString(36)}.pdf`;
}

export async function uploadBrochurePdf(
  requestId: string,
  filename: string,
  bytes: Uint8Array,
): Promise<string> {
  const db = createServiceClient();
  const path = brochurePath(requestId, filename);
  const { error } = await db.storage
    .from(PROPOSALS_BUCKET)
    .upload(path, bytes, { contentType: "application/pdf", upsert: true });
  if (error) throw new Error(`brochure upload failed: ${error.message}`);
  const { data, error: signErr } = await db.storage
    .from(PROPOSALS_BUCKET)
    .createSignedUrl(path, 5 * 365 * 24 * 3600);
  if (signErr || !data?.signedUrl) {
    throw new Error(`brochure signed URL failed: ${signErr?.message ?? "no url"}`);
  }
  return data.signedUrl;
}

/** Create a one-time signed UPLOAD URL so the BROWSER can put a large brochure
 *  PDF straight into our storage, bypassing Vercel's ~4.5MB serverless body cap.
 *  Returns the same brochures/<id>/<slug>-<ts>.pdf path scheme as uploadBrochurePdf
 *  plus the upload token. The client uploads with uploadToSignedUrl(path, token, file),
 *  then the finalize-brochure action mints a long-lived signed DOWNLOAD URL. */
export async function createBrochureUploadUrl(
  requestId: string,
  filename: string,
): Promise<{ path: string; token: string }> {
  const db = createServiceClient();
  const path = brochurePath(requestId, filename);
  const { data, error } = await db.storage
    .from(PROPOSALS_BUCKET)
    .createSignedUploadUrl(path);
  if (error || !data?.token) {
    throw new Error(`brochure upload URL failed: ${error?.message ?? "no token"}`);
  }
  return { path, token: data.token };
}

/** Time-limited signed URL to the (private) proposal PDF — for sharing by
 *  WhatsApp or manually, without making the bucket public. Default 7 days. */
export async function getSignedProposalUrl(
  path: string,
  expiresIn = 7 * 24 * 3600,
): Promise<string> {
  const db = createServiceClient();
  const { data, error } = await db.storage
    .from(PROPOSALS_BUCKET)
    .createSignedUrl(path, expiresIn);
  if (error || !data?.signedUrl) {
    throw new Error(`signed URL failed: ${error?.message ?? "no url"}`);
  }
  return data.signedUrl;
}

// The Helm — George's supplier address book (2026-07-16). His regular central
// agencies, kept in ONE settings row (key helm_supplier_book, no migration).
// v2 (same day): each entry carries an `info` line — what fleet that address
// actually covers and the budget seen on their own site — so a non-broker
// employee can pick recipients without knowing the suppliers by heart. Info
// lines come from verified research + George's own edits; never invented.
// First read with an empty book SEEDS the emails from history (inquiry log
// lines + saved agency fields). Manual additions persist forever; removal
// only edits the book, never any request.

import { createServiceClient } from "@/lib/supabase-server";
import { getSetting, setSetting } from "@/lib/google-api";

const KEY = "helm_supplier_book";
const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
const INFO_MAX = 400;
const NAME_MAX = 60;

/** `name` = the company as a human knows it ("Istion Yachting"); `info` =
 *  category lines separated by "|", each "Category: net fee range" — e.g.
 *  "Catamarans: EUR 10-60k/wk | Motor yachts: EUR 30-500k/wk". The UI renders
 *  each segment on its own line so a non-broker matches a request's budget
 *  and boat type at a glance. */
export type SupplierEntry = { email: string; name: string; info: string };

export function isValidSupplierEmail(s: string): boolean {
  return /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(s.trim());
}

/** Accepts EVERY stored shape — v1 plain strings, v2 {email, info}, v3
 *  {email, name, info} — so the book survives its own upgrades with zero
 *  migration. */
function normalize(list: unknown[]): SupplierEntry[] {
  const seen = new Map<string, SupplierEntry>();
  for (const raw of list) {
    let email = "";
    let name = "";
    let info = "";
    if (typeof raw === "string") email = raw;
    else if (raw && typeof raw === "object") {
      email = String((raw as { email?: unknown }).email ?? "");
      name = String((raw as { name?: unknown }).name ?? "");
      info = String((raw as { info?: unknown }).info ?? "");
    }
    email = email.trim().toLowerCase();
    if (!isValidSupplierEmail(email)) continue;
    name = name.replace(/\s+/g, " ").trim().slice(0, NAME_MAX);
    info = info.replace(/\s+/g, " ").trim().slice(0, INFO_MAX);
    const prev = seen.get(email);
    // Keep the richest record when the same address appears twice.
    if (!prev || name.length + info.length > prev.name.length + prev.info.length) {
      seen.set(email, { email, name, info });
    }
  }
  // Sort by display name (email as fallback) — the list reads like a phonebook.
  return Array.from(seen.values()).sort((a, b) =>
    (a.name || a.email).localeCompare(b.name || b.email),
  );
}

async function seedFromHistory(): Promise<SupplierEntry[]> {
  const db = createServiceClient();
  const found: string[] = [];
  const { data: msgs } = await db
    .from("helm_messages")
    .select("body")
    .like("body", "[Central agency inquiry ->%")
    .limit(500);
  for (const m of msgs ?? []) {
    // Addresses live in the first line: "[... -> a@x, b@y - sent individually ...]"
    const firstLine = String(m.body ?? "").split("\n")[0];
    found.push(...(firstLine.match(EMAIL_RE) ?? []));
  }
  const { data: reqs } = await db
    .from("helm_requests")
    .select("central_agency_email")
    .not("central_agency_email", "is", null)
    .limit(500);
  for (const r of reqs ?? []) {
    found.push(...(String(r.central_agency_email ?? "").match(EMAIL_RE) ?? []));
  }
  return normalize(found);
}

async function saveBook(entries: SupplierEntry[]): Promise<void> {
  await setSetting(KEY, JSON.stringify(entries));
}

export async function getSupplierBook(): Promise<SupplierEntry[]> {
  const raw = await getSetting(KEY);
  if (raw) {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return normalize(parsed);
    } catch { /* corrupted value -> reseed below */ }
  }
  const seeded = await seedFromHistory();
  if (seeded.length) await saveBook(seeded);
  return seeded;
}

export async function addToSupplierBook(emails: string[]): Promise<SupplierEntry[]> {
  const book = await getSupplierBook();
  const next = normalize([...book, ...emails]);
  if (next.length !== book.length) await saveBook(next);
  return next;
}

export async function removeFromSupplierBook(email: string): Promise<SupplierEntry[]> {
  const book = await getSupplierBook();
  const target = email.trim().toLowerCase();
  const next = book.filter((e) => e.email !== target);
  if (next.length !== book.length) await saveBook(next);
  return next;
}

/** George (or his employee) edits a supplier's name/info inline; empty clears. */
export async function setSupplierFields(
  email: string,
  fields: { name?: string; info?: string },
): Promise<SupplierEntry[]> {
  const book = await getSupplierBook();
  const target = email.trim().toLowerCase();
  const next = book.map((e) => {
    if (e.email !== target) return e;
    const out = { ...e };
    if (fields.name !== undefined) out.name = fields.name.replace(/\s+/g, " ").trim().slice(0, NAME_MAX);
    if (fields.info !== undefined) out.info = fields.info.replace(/\s+/g, " ").trim().slice(0, INFO_MAX);
    return out;
  });
  await saveBook(next);
  return next;
}

// src/lib/helm/whitelabel.ts
// =============================================================
// HARD WHITE-LABEL GUARD for travel-agent proposals.
//
// A travel agent presents the PDF to their own client under their own name.
// Before a travel_agent PDF is finalized we scan the rendered HTML, the PDF
// title (document metadata) AND the download filename, case-insensitively,
// for any token that would betray George Yachts. If ANY is found we FAIL the
// generation loudly rather than silently ship a leaky white-label. This
// mirrors the existing source-agency strip safety pattern in extract.ts.
// =============================================================

// Deny-list. Order longest/most-specific first for clearer hit labels; the
// scan reports every distinct match. Tokens are lowercase substrings.
const DENY: { token: string; label: string }[] = [
  { token: "george yachts", label: "George Yachts" },
  { token: "georgeyachts", label: "georgeyachts (domain / email)" },
  { token: "biniaris", label: "Biniaris" },
  { token: "george", label: "George" },
  { token: "6970380999", label: "Athens phone" },
  { token: "7867988798", label: "Miami / WhatsApp phone" },
  { token: "calendly", label: "Calendly CTA" },
  { token: "ghost", label: "GHOST colophon" },
  { token: "sheridan", label: "Sheridan address" },
  { token: "wy 82801", label: "WY 82801 address" },
  { token: "82801", label: "ZIP 82801" },
  { token: "30 n gould", label: "street address" },
  { token: "gould st", label: "street address" },
];

/** Returns the distinct deny-list labels found across the given parts.
 *  We scan only what the recipient can actually see: the <body> markup + the
 *  PDF title/filename. The <style> block is stripped first because it is never
 *  rendered AND it legitimately contains both 3 MB base64 font blobs (which by
 *  chance hold short ASCII runs like "george") and a CSS comment mentioning
 *  "George-hosted URLs". Remaining base64 (body images) is stripped too. */
export function scanWhiteLabel(...parts: (string | null | undefined)[]): string[] {
  const hay = parts.filter(Boolean).join("\n")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")        // CSS: fonts + comments, never rendered
    .replace(/data:[^,]*,[A-Za-z0-9+/=]+/g, " ")       // body-embedded base64 images
    .toLowerCase();
  const hits = new Set<string>();
  for (const d of DENY) if (hay.includes(d.token)) hits.add(d.label);
  return [...hits];
}

/** Throws if any George-Yachts token survives in a travel-agent document. */
export function assertWhiteLabelClean(parts: { html: string; title?: string; filename?: string }): void {
  const hits = scanWhiteLabel(parts.html, parts.title, parts.filename);
  if (hits.length) {
    throw new Error(
      `White-label guard FAILED: the travel-agent document still contains [${hits.join(", ")}]. ` +
      `Generation was aborted so nothing leaky is shipped. Check the proposal copy and footer.`,
    );
  }
}

/**
 * Holiday detection by country.
 * Returns holiday names that fall on today's date for the given country.
 */

interface Holiday {
  name: string;
  /** Month (1-12) */
  month: number;
  /** Day (1-31) */
  day: number;
  /** ISO 3166-1 country codes or "ALL" */
  countries: string[];
}

const FIXED_HOLIDAYS: Holiday[] = [
  // Christmas Eve
  {
    name: "Christmas Eve",
    month: 12,
    day: 24,
    countries: ["US", "GB", "DE", "FR", "IT", "ES", "NL", "BE", "AT", "CH", "SE", "DK", "NO", "FI", "AU", "GR", "PT", "IE", "PL", "CZ"],
  },
  // Christmas Day
  {
    name: "Christmas",
    month: 12,
    day: 25,
    countries: ["US", "GB", "DE", "FR", "IT", "ES", "NL", "BE", "AT", "CH", "SE", "DK", "NO", "FI", "AU", "GR", "PT", "IE", "PL", "CZ", "CA", "NZ", "BR", "MX"],
  },
  // New Year's Eve
  {
    name: "New Year's Eve",
    month: 12,
    day: 31,
    countries: ["ALL"],
  },
  // New Year's Day
  {
    name: "New Year",
    month: 1,
    day: 1,
    countries: ["ALL"],
  },
];

/**
 * Country name to ISO code mapping for flexible lookups.
 */
const COUNTRY_NAME_TO_CODE: Record<string, string> = {
  "United States": "US",
  "United Kingdom": "GB",
  "Germany": "DE",
  "France": "FR",
  "Italy": "IT",
  "Spain": "ES",
  "Greece": "GR",
  "Australia": "AU",
  "Canada": "CA",
  "Netherlands": "NL",
  "Belgium": "BE",
  "Austria": "AT",
  "Switzerland": "CH",
  "Sweden": "SE",
  "Denmark": "DK",
  "Norway": "NO",
  "Finland": "FI",
  "Portugal": "PT",
  "Ireland": "IE",
  "Poland": "PL",
  "Czech Republic": "CZ",
  "New Zealand": "NZ",
  "Brazil": "BR",
  "Mexico": "MX",
  "Monaco": "MC",
  "Croatia": "HR",
  "Turkey": "TR",
  "Cyprus": "CY",
  "Malta": "MT",
};

function normalizeCountry(country: string): string {
  if (country.length === 2) return country.toUpperCase();
  return COUNTRY_NAME_TO_CODE[country] ?? country.toUpperCase().slice(0, 2);
}

/**
 * Returns holiday names for today based on the contact's country.
 * @param country - Country name or ISO 3166-1 alpha-2 code
 * @param date - Optional date override (defaults to today)
 */
export function getHolidaysToday(country: string, date?: Date): string[] {
  const now = date ?? new Date();
  const month = now.getMonth() + 1;
  const day = now.getDate();
  const code = normalizeCountry(country);

  return FIXED_HOLIDAYS
    .filter(
      (h) =>
        h.month === month &&
        h.day === day &&
        (h.countries.includes("ALL") || h.countries.includes(code))
    )
    .map((h) => h.name);
}

