const WINDOW_START_HOUR = 18;
const WINDOW_END_HOUR = 19; // last legal full hour
const WINDOW_END_MINUTE = 30; // + up to this minute
const MIN_GAP_MS = 18 * 60 * 60 * 1000; // 18h between feed posts
