export function inferReligion(opts: {
  country?: string | null;
  first_name?: string | null;
  last_name?: string | null;
  email?: string | null;
}): Religion {
  const country = opts.country?.trim();
  const first = opts.first_name?.trim().toLowerCase() ?? "";
  const last = opts.last_name?.trim().toLowerCase() ?? "";
  const emailDomain =
    opts.email?.split("@")[1]?.toLowerCase().trim() ?? "";

  // STRONGEST: Greek name pattern → orthodox (regardless of country —
  // Greek diaspora is overwhelmingly Orthodox even in US/UK/AU)
  if (first && GREEK_FIRST_NAMES.has(first)) return "orthodox";
  if (last && GREEK_NAME_RE.test(last)) return "orthodox";

  // Greek email domain → orthodox
  if (emailDomain.endsWith(".gr") || emailDomain.endsWith(".cy")) {
    return "orthodox";
  }

  // STRONG: name signals override Western country defaults for
  // Muslim / Hindu names
  if (first) {
    if (MUSLIM_NAME_PREFIXES.some((p) => first.startsWith(p))) return "muslim";
    if (HINDU_NAME_PREFIXES.some((p) => first.startsWith(p))) return "hindu";
  }

  // Country-based — but ONLY for explicit signals. The old behaviour
  // assigned protestant to anyone in US/UK/etc which inflated the
  // protestant count to 73% (impossible for a Greek broker). Now
  // country gives religion ONLY when the country is explicitly set.
  if (!country) return "unknown";
  if (ORTHODOX_COUNTRIES.has(country)) return "orthodox";
  if (MUSLIM_COUNTRIES.has(country)) return "muslim";
  if (HINDU_COUNTRIES.has(country)) return "hindu";
  if (JEWISH_COUNTRIES.has(country)) return "jewish";
  // Catholic / Protestant — only when there's no Greek-name evidence
  // (already checked above).
  if (CATHOLIC_COUNTRIES.has(country)) return "catholic";
  if (PROTESTANT_COUNTRIES.has(country)) return "protestant";
  return "unknown";
}

// Pinterest v5 client — pure-fetch wrapper around the official
// Pinterest API. Free forever (1 000 API calls/day on the public
// tier; we use 1-3 calls per day).
//
// Setup (one-off, manual):
//   1. Create a Pinterest Business account (free)
//   2. Apply for API access at developers.pinterest.com → get
//      app_id + app_secret
//   3. Run OAuth via /api/auth/pinterest/start and grant access
//      to the boards we want to publish to
//   4. The callback handler captures the refresh_token and stores
//      it as PINTEREST_REFRESH_TOKEN in Vercel env
//
// Daily cron uses the refresh_token to mint a short-lived access
// token, then POSTs to /v5/pins.

const API = "https://api.pinterest.com/v5";

interface AccessTokenCache {
  token: string | null;
  expiresAt: number;
}
const _cache: AccessTokenCache = { token: null, expiresAt: 0 };

type Result<T> = ({ ok: true } & T) | { ok: false; error: string };

async function refreshAccessToken(): Promise<string | null> {
  const appId = process.env.PINTEREST_APP_ID;
  const appSecret = process.env.PINTEREST_APP_SECRET;
  const refreshToken = process.env.PINTEREST_REFRESH_TOKEN;
  if (!appId || !appSecret || !refreshToken) return null;
  if (_cache.token && Date.now() < _cache.expiresAt - 60_000) {
    return _cache.token;
  }
  try {
    const basic = Buffer.from(`${appId}:${appSecret}`).toString("base64");
    const body = new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: refreshToken,
    });
    const res = await fetch(`${API}/oauth/token`, {
      method: "POST",
      headers: {
        Authorization: `Basic ${basic}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body,
    });
    if (!res.ok) {
      console.error("[pinterest] token refresh failed", res.status, await res.text());
      return null;
    }
    const json = await res.json();
    const accessToken = json.access_token as string | undefined;
    const ttlSec = (json.expires_in as number) || 3600;
    if (!accessToken) return null;
    _cache.token = accessToken;
    _cache.expiresAt = Date.now() + ttlSec * 1000;
    return accessToken;
  } catch (e) {
    console.error("[pinterest] token refresh threw:", e);
    return null;
  }
}

async function callPinterest<T = any>(
  path: string,
  options: { method?: "GET" | "POST" | "DELETE"; body?: any } = {},
): Promise<{ ok: true; data: T } | { ok: false; error: string; status: number }> {
  const token = await refreshAccessToken();
  if (!token) {
    return { ok: false, error: "Pinterest not configured (missing env)", status: 0 };
  }
  try {
    const url = path.startsWith("http") ? path : `${API}${path}`;
    const res = await fetch(url, {
      method: options.method ?? "GET",
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
        ...(options.body ? { "Content-Type": "application/json" } : {}),
      },
      body: options.body ? JSON.stringify(options.body) : undefined,
    });
    const j = await res.json().catch(() => ({}));
    if (!res.ok) {
      return {
        ok: false,
        error: j?.message ?? j?.code ?? `HTTP ${res.status}`,
        status: res.status,
      };
    }
    return { ok: true, data: j as T };
  } catch (e: any) {
    return { ok: false, error: e?.message ?? "fetch failed", status: 0 };
  }
}

export interface PinterestBoard {
  id: string;
  name: string;
  privacy: string;
}

export async function listBoards(): Promise<Result<{ boards: PinterestBoard[] }>> {
  const res = await callPinterest<{ items: PinterestBoard[] }>("/boards");
  if (!res.ok) return { ok: false, error: res.error };
  return { ok: true, boards: res.data.items ?? [] };
}

export interface PinArgs {
